window.KB_DASHBOARD_UNITS = [{"unit":1,"theme":"credit – worm","cards":[{"w":"credit","p":"n.","d":"","c":"信用、信貸","s":"If you don't pay your bills on time, it will damage your credit and make it hard to get a loan.","t":"如果你不準時付帳單，會損害你的信用，讓你很難獲得貸款。"},{"w":"credit card","p":"phr.","d":"","c":"信用卡","s":"He prefers using a credit card instead of cash because it is more convenient and he can earn reward points.","t":"他比起現金更喜歡使用信用卡，因為更方便且能賺取獎勵點數。"},{"w":"credit","p":"n.","d":"","c":"功勞、讚揚","s":"Although many people worked on the project, the manager took all the credit for its success.","t":"儘管許多人參與了這個專案，經理卻把成功的功勞全攬在自己身上。"},{"w":"take credit","p":"phr.","d":"","c":"邀功、歸功於","s":"A good leader should never take credit for the hard work of their team members.","t":"一位好的領導者不應該把團隊成員的努力歸功於自己。"},{"w":"credit","p":"n.","d":"","c":"學分","s":"You need to complete at least 120 credits in order to graduate from this university.","t":"你需要修滿至少 120 個學分才能從這間大學畢業。"},{"w":"incredible","p":"adj.","d":"","c":"難以置信的","s":"The magician's tricks were so incredible that the audience couldn't believe their eyes.","t":"這位魔術師的把戲太難以置信，觀眾無法相信自己的眼睛。"},{"w":"natural","p":"adj.","d":"","c":"自然的","s":"The park's beauty lies in its natural landscape, with untouched forests and serene lakes.","t":"這個公園之美在於其自然景觀，擁有原始的森林和寧靜的湖泊。"},{"w":"nature","p":"n.","d":"","c":"大自然","s":"Spending time in nature can have a calming and rejuvenating effect on people.","t":"在大自然中度過時間可以對人們產生平靜和振奮的效果。"},{"w":"naturally","p":"adv.","d":"","c":"自然地","s":"Cats are naturally curious creatures, often exploring their surroundings with great interest.","t":"貓是天生好奇的生物，通常以極大的興趣探索著周圍的環境。"},{"w":"be curious about","p":"phr.","d":"","c":"對⋯⋯好奇","s":"Children tend to be curious about the world around them.","t":"孩子們往往對他們周圍的世界充滿好奇心。"},{"w":"curiosity","p":"n.","d":"","c":"好奇心","s":"The scientist's curiosity led to groundbreaking discoveries in the field of astronomy.","t":"這位科學家的好奇心在天文學領域帶來了突破性的發現。"},{"w":"nevertheless","p":"adv.","d":"","c":"然而；不過","s":"The weather was gloomy; nevertheless, we decided to go for a hike.","t":"天氣陰沉；然而，我們決定去遠足。"},{"w":"impress","p":"v.","d":"","c":"使...留下深刻印象","s":"He tried to impress his new boss by staying late at the office and finishing all his reports ahead of schedule.","t":"他試圖透過加班和提前完成所有報告來給新老闆留下深刻印象。"},{"w":"impressive","p":"adj.","d":"","c":"令人印象深刻的","s":"The young athlete's performance was truly impressive, as she broke three school records in a single day.","t":"那位年輕運動員的表現確實令人印象深刻，她在一天內打破了三項學校紀錄。"},{"w":"impressed","p":"adj.","d":"","c":"感到印象深刻的","s":"The judges were deeply impressed with the student's creative solution to the environmental problem.","t":"評審對該學生解決環境問題的創意方案感到印象深刻。"},{"w":"leave a... impression on","p":"phr.","d":"","c":"給...留下...的印象","s":"His kindness and patience left a lasting impression on the children he taught during the summer camp.","t":"他的善良與耐心給他在夏令營教過的孩子們留下了持久的印象。"},{"w":"make a... impression on","p":"phr.","d":"","c":"對...產生...的印象","s":"It is important to make a good impression on the interviewer if you want to get the job.","t":"如果你想得到這份工作，給面試官留下好印象是很重要的。"},{"w":"distinct","p":"adj.","d":"","c":"有區別的；明顯的","s":"The two species have distinct characteristics that set them apart from each other.","t":"這兩個物種具有明顯的特徵，使它們彼此區別開來。"},{"w":"distinct","p":"adj.","d":"","c":"截然不同的","s":"There is a distinct difference between the two products, even though they look similar at first glance.","t":"雖然這兩款產品乍看之下很像，但它們之間有著截然不同的區別。"},{"w":"distinctive","p":"adj.","d":"","c":"獨特的、有特色的","s":"The male peacock is known for its distinctive tail feathers, which it uses to attract mates.","t":"雄孔雀以其獨特的尾羽聞名，牠用尾羽來吸引配偶。"},{"w":"distinction","p":"n.","d":"","c":"區別；卓越、殊榮","s":"She passed the bar exam with distinction, earning one of the highest scores in the country.","t":"她以優異的成績通過了律師執照考試，獲得了全國最高分之一的殊榮。"},{"w":"phenomenon","p":"n.","d":"","c":"現象","s":"The Northern Lights are a natural phenomenon that attracts tourists from around the world.","t":"北極光是一個吸引來自世界各地的遊客的自然現象。"},{"w":"natural phenomenon","p":"phr.","d":"","c":"自然現象","s":"The Northern Lights are a spectacular natural phenomenon that attracts thousands of tourists to the Arctic every year.","t":"北極光是一種壯觀的自然現象，每年吸引數千名遊客前往北極。"},{"w":"phenomenal","p":"adj.","d":"","c":"非凡的、驚人的","s":"The company has seen phenomenal growth over the past year, with its stock price nearly doubling.","t":"該公司在過去一年中取得了驚人的增長，其股價幾乎翻了一倍。"},{"w":"trend","p":"n.","d":"","c":"趨勢、傾向","s":"There is a growing trend toward remote work as more companies realize the benefits of flexibility.","t":"隨著越來越多公司意識到靈活性的好處，遠距辦公的趨勢正日益增長。"},{"w":"trendy","p":"adj.","d":"","c":"時髦的、流行的","s":"This neighborhood is famous for its trendy cafes and boutiques that attract many young people.","t":"這個社區以其時髦的咖啡館和精品店聞名，吸引了許多青年。"},{"w":"science","p":"n.","d":"","c":"科學","s":"Advancements in science have allowed us to explore deep space and develop cures for many diseases.","t":"科學的進步使我們能夠探索深太空並開發出許多疾病的療法。"},{"w":"scientist","p":"n.","d":"","c":"科學家","s":"The scientist spent years in the laboratory conducting experiments to test her new hypothesis.","t":"這位科學家在實驗室裡花了數年時間進行實驗，以測試她的新假設。"},{"w":"scientific","p":"adj.","d":"","c":"科學的","s":"The experiment was conducted following strict scientific methods to ensure accurate results.","t":"實驗是按照嚴格的科學方法進行的，以確保準確的結果。"},{"w":"scientifically","p":"adv.","d":"","c":"科學地、合乎科學地","s":"It has been scientifically proven that regular exercise can significantly improve mental health and reduce stress.","t":"定期運動已被科學證明可以顯著改善心理健康並減輕壓力。"},{"w":"puzzle","p":"n.","d":"","c":"謎題；難題","s":"The crossword puzzle in today's newspaper was quite challenging.","t":"今天的報紙上的填字遊戲謎題非常具有挑戰性。"},{"w":"puzzle","p":"v.","d":"","c":"使困惑；使感到困惑","s":"The complex instructions puzzled many participants, causing them to seek help.","t":"複雜的說明讓許多參與者感到困惑，迫使他們尋求幫助。"},{"w":"puzzled","p":"adj.","d":"","c":"感到困惑的","s":"The detective had a puzzled look on his face because the evidence at the crime scene didn't make sense.","t":"偵探臉上帶著困惑的神情，因為犯罪現場的證據並不合理。"},{"w":"puzzling","p":"adj.","d":"","c":"令人費解的、撲朔迷離的","s":"It was a puzzling mystery why all the lights in the building suddenly went out at the same time.","t":"建築物內所有的燈為何突然同時熄滅，是一個令人費解的謎團。"},{"w":"perfect","p":"adj.","d":"","c":"完美的","s":"Her dance performance was flawless and truly perfect.","t":"她的舞蹈表演無懈可擊，真的很完美。"},{"w":"perfection","p":"n.","d":"","c":"完美","s":"The artist was a perfectionist, always striving for perfection in every brushstroke.","t":"這位藝術家是個完美主義者，總是在每一筆畫中追求完美。"},{"w":"therefore","p":"adv.","d":"","c":"因此","s":"The weather forecast predicted rain; therefore, we decided to reschedule our picnic.","t":"天氣預報預測會下雨，因此我們決定重新安排我們的野餐。"},{"w":"lay","p":"v.","d":"","c":"下蛋","s":"Most reptiles lay eggs rather than giving birth to live young.","t":"大多數爬行動物會下蛋，而不是生下活體幼崽。"},{"w":"lay","p":"v.","d":"","c":"放置物品","s":"She asked her son to lay his toys before dinner.","t":"她叫兒子在晚餐前將玩具放好。"},{"w":"lie","p":"v.","d":"","c":"說謊","s":"He lied to his parents about where he was last night, and now he feels guilty about it.","t":"他對父母謊報了昨天晚上他在哪裡，現在他對此感到內疚。"},{"w":"lie","p":"v.","d":"","c":"躺；坐落於","s":"After a long day of hiking, the exhausted travelers lay down on the grass to rest.","t":"經過一整天的健行後，疲憊的旅人躺在草地上休息。"},{"w":"category","p":"n.","d":"","c":"類別；種類","s":"The products are divided into different categories based on their features.","t":"這些產品根據其特點被分成不同的類別。"},{"w":"categorize","p":"v.","d":"","c":"分類","s":"The library staff had to categorize the books according to their genres.","t":"圖書館工作人員需要根據書籍的類型對其進行分類。"},{"w":"worm","p":"n.","d":"","c":"蟲子；蠕蟲","s":"The child was fascinated by the tiny worm crawling in the garden.","t":"孩子對在花園裡爬行的小蟲子非常著迷。"}]},{"unit":2,"theme":"jewelry – odds","cards":[{"w":"jewelry","p":"n.","d":"decorative objects such as rings or necklaces worn on the body.","c":"珠寶","s":"She wore a stunning piece of jewelry that sparkled in the sunlight.","t":"她戴著一件在陽光下閃閃發亮的華麗珠寶。"},{"w":"jewel","p":"n.","d":"a precious stone used in jewelry.","c":"寶石","s":"The royal crown was adorned with a magnificent jewel at its center.","t":"皇冠上飾有一顆華麗的中央寶石。"},{"w":"design","p":"n.","d":"a plan or idea for how something looks or is made.","c":"設計","s":"The architect's design for the new building incorporated both functionality and aesthetics.","t":"建築師對新建築的設計融合了功能性和美學。"},{"w":"designer","p":"n.","d":"a person who plans or creates designs.","c":"設計師","s":"The fashion designer showcased their latest collection on the runway.","t":"這家時尚設計師在伸展台上展示了他們的最新系列。"},{"w":"blood cell","p":"n.","d":"a very small part of blood that carries oxygen or fights disease.","c":"血球","s":"White blood cells help the body fight infections.","t":"白血球幫助身體抵抗感染。"},{"w":"cell phone","p":"n.","d":"a portable phone used for calling and messaging.","c":"手機","s":"Nowadays, almost everyone has a cell phone and relies on it for communication and various tasks.","t":"現在幾乎每個人都有手機，並且依賴它進行通信和各種任務。"},{"w":"wisdom","p":"n.","d":"the ability to make good and careful decisions.","c":"智慧","s":"The elderly woman's wisdom and life experience were evident in her thoughtful advice.","t":"這位老婦人的智慧和人生經驗在她的深思熟慮的建議中顯而易見。"},{"w":"tissue","p":"n.","d":"soft paper used for cleaning or wiping the face.","c":"面紙","s":"She used a tissue to wipe away her tears after watching the touching movie.","t":"她在觀看感人電影後用面紙擦去眼淚。"},{"w":"tissue","p":"n.","d":"a group of similar cells in a living body.","c":"組織","s":"The tissue in the human body is composed of specialized cells that perform specific functions.","t":"人體的組織由專門的細胞組成，執行特定的功能。"},{"w":"goal","p":"n.","d":"something you want to achieve.","c":"目標","s":"Setting clear goals is important for achieving success in both personal and professional life.","t":"設定明確的目標對於在個人和職業生活中取得成功至關重要。"},{"w":"involvement","p":"n.","d":"the act of taking part in something.","c":"參與；涉及","s":"Her involvement in local environmental initiatives made a positive impact on the community.","t":"她參與當地環保活動，對社區產生了積極的影響。"},{"w":"discussion","p":"n.","d":"a talk in which people share ideas or opinions.","c":"討論","s":"The discussion about the company's future direction lasted for hours and included lively debates.","t":"關於公司未來方向的討論持續了幾個小時，包括熱烈的辯論。"},{"w":"engineer","p":"n.","d":"a person who designs or builds machines or systems.","c":"工程師","s":"The civil engineer was responsible for designing the new bridge that would connect the two cities.","t":"這位土木工程師負責設計連接兩座城市的新橋樑。"},{"w":"engineering","p":"n.","d":"the study and practice of designing and building things.","c":"工程學","s":"She pursued a degree in engineering and went on to design innovative solutions for urban development.","t":"她攻讀工程學學位，並致力於為城市發展設計創新解決方案。"},{"w":"odds","p":"n.","d":"the chance or possibility that something will happen.","c":"可能性；機會","s":"Despite the odds being against them, they managed to overcome challenges and succeed.","t":"儘管機會不利，他們成功克服了挑戰。"}]},{"unit":3,"theme":"sting – electricity","cards":[{"w":"sting","p":"n.","d":"","c":"刺痛；螫傷","s":"The sting from the bee was excruciating.","t":"被蜜蜂螫傷的刺痛讓人痛苦不堪。"},{"w":"sting","p":"v.","d":"","c":"螫傷；刺痛","s":"The bee stung me, and my arm immediately swelled up.","t":"蜜蜂螫了我，我的手臂立刻腫了起來。"},{"w":"take the sting out of","p":"phr.","d":"","c":"消除痛苦","s":"His kind words took the sting out of her criticism.","t":"他的友善話語減輕了她的批評之苦。"},{"w":"contrary to","p":"phr.","d":"","c":"與...相反+N","s":"Contrary to popular belief, cats can be trained.","t":"與普遍信仰相反，貓是可以被訓練的。"},{"w":"on the contrary","p":"phr.","d":"","c":"相反地；恰恰相反","s":"She expected him to be angry; on the contrary, he smiled.","t":"她以為他會生氣，但恰恰相反，他微笑了。"},{"w":"be (put) in danger","p":"phr.","d":"","c":"處於危險中","s":"The hiker realized he was in danger when he lost the trail.","t":"遠足者意識到他迷失了路徑，處於危險中。"},{"w":"endangered species","p":"phr.","d":"","c":"瀕臨絕種的物種","s":"The environmentalists are making efforts to protect endangered species from extinction.","t":"環保人士正在努力保護瀕臨絕種的物種免於滅絕。"},{"w":"put ... in danger","p":"phr.","d":"","c":"使...處於危險中","s":"His reckless driving put the passengers in danger.","t":"他魯莽的駕駛使乘客們處於危險之中。"},{"w":"pose a risk to","p":"phr.","d":"","c":"造成風險；帶來危險","s":"The construction site poses a severe risk to pedestrians.","t":"施工現場對行人構成嚴重的風險。"},{"w":"pose a threat to","p":"phr.","d":"","c":"對...構成威脅","s":"The foreign invasive species poses a significant threat to the native species and the ecosystem.","t":"這種外來的入侵物種對原生物種和生態系統構成了重大威脅。"},{"w":"pose","p":"n.","d":"","c":"姿勢；態度","s":"Her confident pose displays her authority.","t":"她自信的姿勢散發著權威。"},{"w":"bacteria","p":"n.","d":"","c":"細菌(複數)","s":"Some bacteria can be beneficial to human health.","t":"一些細菌對人類健康有益。"},{"w":"antibacterial","p":"adj.","d":"","c":"抗菌的","s":"The soap contains antibacterial properties特性 that help prevent infections.","t":"這款肥皂具有抗菌特性，有助於預防感染。"},{"w":"virus","p":"n.","d":"","c":"病毒","s":"The virus spread quickly through the population via airborne droplets.","t":"這種病毒在人群中透過飛沫迅速蔓延開來。"},{"w":"viral","p":"adj.","d":"","c":"病毒性的；迅速傳播的","s":"Many elders are volnerable to virus and die of viral infection.","t":"許多長者對病毒很沒抵抗力，並死於病毒感染。"},{"w":"go viral","p":"phr.","d":"","c":"迅速傳播；爆紅","s":"The catchy tune made the song go viral on social media.","t":"這支引人入勝的曲調使得這首歌在社群媒體上迅速爆紅。"},{"w":"computer virus","p":"phr.","d":"","c":"電腦病毒","s":"His computer was infected with a computer virus.","t":"他的電腦感染上了一個電腦病毒。"},{"w":"product","p":"n.","d":"","c":"產品；成果","s":"The company launched推出 a new product line.","t":"這家公司推出了一條新的產品線。"},{"w":"produce","p":"v.","d":"","c":"生產；製造","s":"The factory produces consumer goods.","t":"這家工廠生產消費品。"},{"w":"produce","p":"n.","d":"","c":"農產品；產物","s":"The region is known for its high-quality agricultural produce.","t":"這個地區以高質量的農產品而聞名。"},{"w":"production","p":"n.","d":"","c":"生產；製造","s":"The production process requires careful planning.","t":"生產過程需要仔細的規劃。"},{"w":"productive","p":"adj.","d":"","c":"有生產力的；多產的","s":"The team had a productive brainstorming session=meeting.","t":"這個團隊有一次富有成果的頭腦風暴會議。"},{"w":"productivity","p":"n.","d":"","c":"生產力；生產效率","s":"The new AI (artificial intelligence) software improved productivity within the employees.","t":"這個新AI軟體提高了員工的生產效率。"},{"w":"harsh smell","p":"phr.","d":"","c":"刺鼻的氣味","s":"The cleaning solution溶劑 had a harsh smell.","t":"這個清潔劑有一種刺鼻的氣味。"},{"w":"harsh condition","p":"phr.","d":"","c":"惡劣的環境；惡劣的條件","s":"The explorers faced harsh weather conditions during their journey.","t":"探險者在他們的旅程中面臨了惡劣的環境。"},{"w":"harsh comment","p":"phr.","d":"","c":"刻薄的評論；嚴厲的批評","s":"The haters' harsh comments on social media hurt the feelings and reputation of the celebrity.","t":"酸民的嚴厲的評論傷害了這個名人的感情和名聲。"},{"w":"severe","p":"adj.","d":"","c":"嚴重的；嚴峻的","s":"The patient was suffering from severe pain.","t":"病人正遭受著嚴重的疼痛。"},{"w":"chemical","p":"n.","d":"","c":"化學製品；化學藥品","s":"The laboratory stored various chemicals for experiments.","t":"實驗室儲存著各種化學製品用於實驗。"},{"w":"chemical","p":"adj.","d":"","c":"化學的","s":"The scientist conducted chemical analysis on the radioactive substance.","t":"科學家對這種放射性/輻射性物質進行了化學分析。"},{"w":"property","p":"n.","d":"","c":"特性；性能","s":"The properties of this material make it suitable for conducting heat.","t":"這種材料的特性使其適用於傳導熱。"},{"w":"cause","p":"v.","d":"","c":"引起；導致","s":"The heavy rain caused flooding in the low-lying areas.","t":"大雨引起了低洼地區的水災。"},{"w":"cause","p":"n.","d":"","c":"原因；起因","s":"The investigation aimed to determine the cause of the accident.","t":"調查旨在確定事故的原因。"},{"w":"household","p":"adj.","d":"","c":"家庭的","s":"The household appliances were all energy-efficient models.","t":"這些家庭用品都是節能型號。"},{"w":"household","p":"n.","d":"","c":"家庭；家人","s":"The entire household is devoted to the preparation of the party.","t":"整個家庭都投入了籌備派對的工作。"},{"w":"come up with a solution","p":"phr.","d":"","c":"提出解決方案","s":"The team brainstormed for hours to come up with a solution.","t":"團隊開會幾個小時，提出了解決方案。"},{"w":"a solution to a problem","p":"phr.","d":"","c":"解決問題的方法","s":"The engineer devised a solution to the problem that saved a large amount of time and money.","t":"這位工程師設計了解決問題的方法，節省了大量的時間和金錢。"},{"w":"solution","p":"n.","d":"","c":"化學溶劑","s":"The chemist mixed the solution to remove the radioactive substance.","t":"化學家將溶劑混合以去除這個放射性輻射性物質。"},{"w":"solve","p":"v.","d":"","c":"解決；找出答案","s":"The detective worked tirelessly to solve the complex case.","t":"這位偵探不懈努力地解決這個複雜的案件。"},{"w":"plenty of","p":"phr.","d":"","c":"許多；大量","s":"Help yourself to plenty of snacks at the party.","t":"請自行取用派對上許多美味的小吃。"},{"w":"plentiful","p":"adj.","d":"","c":"大量的；豐富的","s":"In the forest, there was a plentiful supply of fresh water.","t":"在森林中，有充足的淡水供應。"},{"w":"manufacture","p":"v.","d":"","c":"製造；生產","s":"The company manufactures high-quality electronics.","t":"這家公司生產高質量的電子產品。"},{"w":"mild flavor","p":"phr.","d":"","c":"淡淡的味道","s":"The dish had a mild flavor that appealed to everyone.","t":"這道菜有一種淡淡的味道，受到了每個人的喜愛。"},{"w":"mild headache","p":"phr.","d":"","c":"輕微的頭痛","s":"She had a mild headache that went away with rest.","t":"她有一點輕微的頭痛，休息後就好了。"},{"w":"mild weather","p":"phr.","d":"","c":"溫和的天氣","s":"The forecast predicted mild weather for the weekend.","t":"天氣預報預測了這個週末將會有溫和的天氣。"},{"w":"defensive","p":"adj.","d":"","c":"防禦的；保護的","s":"The team adopted採用 a defensive strategy to protect their lead.","t":"這個團隊採取了防守策略保護他們的領先地位。"},{"w":"defend","p":"v.","d":"","c":"防禦；保護","s":"He is determined to defend his family from harm.","t":"他下定決心保護家人免受傷害。"},{"w":"defense","p":"n.","d":"","c":"防禦；保護","s":"The fortress was a stronghold of defense against invaders.","t":"這座堡壘是對抗入侵者的堅強防禦。"},{"w":"prevent ... from","p":"phr.","d":"","c":"預防...免於","s":"Regular exercise can help prevent children from illness.","t":"規律的運動可以幫助孩童預防疾病。"},{"w":"prevention","p":"n.","d":"","c":"預防；防止","s":"The campaign focused on the prevention of childhood obesity.","t":"這場運動關注兒童肥胖的預防。"},{"w":"preventive","p":"adj.","d":"","c":"預防的","s":"Taking preventive measures can reduce the risk of infection.","t":"採取預防措施可以降低感染的風險。"},{"w":"electric","p":"adj.","d":"","c":"電的","s":"The car is powered by an electric engine.","t":"這輛汽車由電動引擎提供動力。"},{"w":"electrical","p":"adj.","d":"","c":"電氣的","s":"The engineer repaired the electrical wiring in the building.","t":"工程師修理了建築物內的電氣線路。"},{"w":"electronic","p":"adj.","d":"","c":"電子的","s":"The factory produces electronic components/devices.","t":"這間工廠生產電子元件／設備"},{"w":"electricity","p":"n.","d":"","c":"電力；電能","s":"The city experienced a blackout due to a shortage of electricity.","t":"由於電力短缺，該城市遭遇了停電。"}]},{"unit":4,"theme":"preserve – die out","cards":[{"w":"preserve","p":"v.","d":"","c":"保存；保護","s":"The aboriginal tribe has strived for centuries to preserve the land of their ancestors, and resist modern development.","t":"這個土著部落已經努力了幾個世紀，以保護他們的祖先土地，抵制現代開發。"},{"w":"wildlife preserve","p":"n.","d":"","c":"野生動物保護區","s":"This wildlife preserve is an ecological habitat where endangered species find refuge from human beings.","t":"這個野生動物保護區是一個生態棲息地，瀕臨絕種的物種在這裡尋找避難所，逃避人類。"},{"w":"preservation","p":"n.","d":"","c":"保存；保護","s":"The careful preservation of ancient manuscripts ensures their longevity for future scholars to study and appreciate.","t":"對古老手稿的細心保存確保了它們的長壽，供未來的學者研究和欣賞。"},{"w":"freeze","p":"v.","d":"","c":"凍結；冷凍","s":"In extremely cold climates, water can freeze rapidly, posing dangers to both humans and wildlife.","t":"在極寒的氣候中，水可以迅速凍結，對人類和野生動物都構成危險。"},{"w":"freezer","p":"n.","d":"","c":"冷凍庫","s":"The scientific expedition relied on a mobile freezer to store valuable research specimens.","t":"這次科學考察依賴於一個移動式冷凍庫，以保存價值珍貴的研究標本。"},{"w":"endangered species","p":"n.","d":"","c":"瀕臨絕種的物種","s":"The conservationists' relentless efforts have successfully rescued several endangered species from extinction.","t":"保育人士不懈的努力成功拯救了幾個物種免於滅絕。"},{"w":"cricket","p":"n.","d":"","c":"蟋蟀","s":"The soothing evening was filled with the chirping of crickets, creating an relaxing atmosphere.","t":"安靜的夜晚充滿了蟋蟀的鳴叫聲，營造出一種療愈的氛圍。"},{"w":"cricket","p":"n.","d":"","c":"板球","s":"Growing up in a British school, this Indian dreamed of becoming a professional cricket player.","t":"在英國學校成長過程中，這位印度人夢想成為一名職業板球選手，但生活將他引向了不同的道路。"},{"w":"minus","p":"adj.","d":"","c":"負的；減去","s":"The sudden minus temperatures in winter can be extremely harsh, so we need extra preparation.","t":"冬季突然的負溫度可能特別嚴峻，需要額外的準備。"},{"w":"minus","p":"n.","d":"","c":"缺點；不利因素=disadvantage (n)","s":"One minus of remote work is the potential for increased feelings of isolation among employees.","t":"遠距工作的一個缺點是可能會增加員工感到孤立的潛在可能性。"},{"w":"minus","p":"n.","d":"","c":"減去；除了...之外","s":"The bakery sold 40 croissants, minus the 12 that were given away as free samples.","t":"這家麵包店售出了40個可頌，扣除了12個免費樣品。"},{"w":"plus","p":"n.","d":"","c":"優勢；好處=advantage","s":"One plus of early morning flights is that they often come with lower fares.","t":"早班機的一個優勢是它們通常帶有較低的票價。"},{"w":"degree","p":"n.","d":"","c":"度數；學位","s":"She completed her master's degree in environmental science with honors.","t":"她以榮譽完成了環境科學碩士學位。"},{"w":"bachelor degree","p":"n.","d":"","c":"大學學位","s":"To pursue a bachelor degree in engineering requires dedication and a strong math skill.","t":"追求工程學學士學位需要奉獻精神和強大的數學才能。"},{"w":"to some degree","p":"phr.","d":"","c":"在某種程度上","s":"To some degree, his success can be attributed to his determination and relentless hard work.","t":"他的成功可以歸功於他決心和不懈的努力，這在某種程度上是正確的。"},{"w":"safe","p":"adj.","d":"","c":"安全的","s":"After thorough testing, the government claimed the nuclear wastewater is safe for discharge.","t":"經過全面測試，政府宣稱核汙水是安全可以排放的。"},{"w":"unsafe","p":"adj.","d":"","c":"不安全的","s":"The old building was declared unsafe for living due to structural concerns.","t":"這座老建築被宣佈不適合居住，由於結構問題。"},{"w":"for the sake of safety","p":"phr.","d":"","c":"為了安全起見","s":"We must follow strict safety regulations for the sake of safety during this hazardous experiment.","t":"我們必須堅守嚴格的安全法規，為了在這次危險的實驗中確保安全。"},{"w":"at a ...rate / speed","p":"phr.","d":"","c":"以...的速度","s":"The pandemic has spread at an alarming rate, prompting governments to take action.","t":"疫情以驚人的速度蔓延，促使政府採取行動。"},{"w":"rate","p":"n.","d":"","c":"比率；費用","s":"The rate of inflation has a direct impact on the purchasing power of consumers.","t":"通脹率直接影響了消費者的購買力。"},{"w":"rate","p":"n.","d":"","c":"費用","s":"The rate for using the toll road has increased significantly this year.","t":"使用收費公路的費用今年大幅上升。"},{"w":"fare","p":"n.","d":"","c":"車費；票價","s":"The fare for the subway is quite affordable, making it an attractive option for daily commuters.","t":"地鐵的票價相當實惠，是日常通勤者的一個吸引人的選擇。"},{"w":"charge","p":"n.","d":"","c":"收費；費用","s":"The additional charge for extra baggage on the flight surprises many passengers.","t":"飛機上額外的行李費用讓許多乘客感到驚訝。"},{"w":"entrance fee","p":"n.","d":"","c":"入場費","s":"The entrance fee to the historical site includes access to guided tours.","t":"參觀這個古蹟的入場費包括可以取得導覽。"},{"w":"toll","p":"n.","d":"","c":"(道路、橋樑等的)通行費","s":"Many people prefer to avoid the highway due to the high toll charges.","t":"許多人避免使用高速公路，因為收費很高。"},{"w":"loss","p":"n.","d":"","c":"損失","s":"The stock market crash resulted in a significant financial loss for many investors.","t":"股市崩盤導致許多投資者面臨重大的財務損失。"},{"w":"lost","p":"adj.","d":"","c":"失去的","s":"Her lost luggage was eventually located and returned to her after a long search.","t":"她失去的行李最終在長時間搜索後被找到並歸還給她。"},{"w":"lose","p":"v.","d":"","c":"失去；輸掉","s":"If you lose your way in the forest, remember to stay calm and follow basic survival principles.","t":"如果你在森林中迷路了，請記住保持冷靜，遵循基本的生存原則。"},{"w":"at a loss","p":"phr.","d":"","c":"虧損；不知所措","s":"After the unexpected market crash, many investors were left at a loss, unsure of their next financial move.","t":"在意外的市場崩潰後，許多投資者感到不知所措，不確定下一步的財務舉措。"},{"w":"website","p":"n.","d":"","c":"網站","s":"The company's official website offers resources for both customers and investors.","t":"公司的官方網站為客戶和投資者提供了資源。"},{"w":"percent","p":"n.","d":"","c":"百分比","s":"The elder population has increased by 7 percent in the past decade.","t":"過去十年，老年人口增加了7%。"},{"w":"percentage","p":"n.","d":"","c":"百分比","s":"The percentage of students who scored above 90% on the exam was extremely high.","t":"在考試中獲得90%以上分數的學生百分比非常高。"},{"w":"collect","p":"v.","d":"","c":"收集","s":"Over the years, he managed to collect an impressive collection of antique coins from around the world.","t":"多年來，他成功地收集了來自世界各地的令人印象深刻的古代的錢幣收藏品。"},{"w":"a wide collection of","p":"phr.","d":"","c":"各種各樣的收藏品","s":"The museum boasts a wide collection of artworks, including various cultures and time periods.","t":"博物館擁有各種各樣的藝術品收藏，涵蓋了不同的文化和時期。"},{"w":"collector","p":"n.","d":"","c":"收藏家","s":"The stamp collector traveled the world in search of rare and unique stamps.","t":"這位郵票收藏家周遊世界，尋找罕見和獨特的郵票。"},{"w":"collective","p":"adj.","d":"","c":"集體的；共同的","s":"The collective efforts of the research team led to groundbreaking discoveries in the field of medicine.","t":"研究小組的集體努力在醫學領域取得了開創性的發現。"},{"w":"die out","p":"v.","d":"","c":"滅絕；逐漸消失","s":"Conservationists are working tirelessly to prevent endangered species from dying out.","t":"保育人士正在不懈努力，以防止瀕臨絕種的物種逐漸消失。"}]},{"unit":5,"theme":"tame – increasing","cards":[{"w":"tame","p":"adj.","d":"","c":"馴化的；溫順的","s":"The tame lion in the zoo allowed children to pet and interact with it, which demonstrates its gentle nature.","t":"在動物園中的馴化獅子允許孩子們撫摸和互動，而這展示了它溫馴的天性。"},{"w":"tame","p":"v.","d":"","c":"馴化；馴服","s":"It took several months to tame the wild horse and make it suitable for riding.","t":"需要花好幾個月的時間來馴服這匹野馬，使其適合騎乘。"},{"w":"previous","p":"adj.","d":"","c":"以前的；先前的","s":"Her previous experience as a teacher provided valuable insights for her new role as a school principal.","t":"她以前作為(as)教師的經驗為她新的角色——學校校長——提供了有價值的見解。"},{"w":"a grave situation","p":"adj.","d":"","c":"嚴重（的）局勢；嚴峻（的）情況","s":"The pandemic has created a a grave situation, and we must take immediate action to address it.","t":"這場大流行已經造成了一個嚴重的局勢，我們必須立即采取行動加以應對。"},{"w":"grave","p":"n.","d":"","c":"墳墓","s":"We visited the grave of our ancestors to pay our respects and honor their memory.","t":"我們參拜了我們祖先的墳墓，以表示尊敬和紀念他們。"},{"w":"graveyard","p":"n.","d":"","c":"墓地","s":"The old graveyard was overgrown with ivy, which gives it a hauntingly beautiful appearance.","t":"這座老墓地被常春藤覆蓋，這使它看起來既令人不安又美麗。"},{"w":"bury","p":"v.","d":"","c":"埋葬；掩埋","s":"We have decided to bury our beloved pet in the backyard so that we can visit its resting place whenever we want.","t":"我們決定把我們親愛的寵物埋在後院，這樣我們隨時都能去探望它的安息之地。"},{"w":"burial","p":"n.","d":"","c":"埋葬","s":"The burial ceremony was a solemn and emotional event, as friends and family gathered to say their final goodbyes.","t":"埋葬儀式是一個莊嚴而感人的場合，當朋友和家人聚集在一起致上道別之意。"},{"w":"journal","p":"n.","d":"","c":"雜誌刊物","s":"Her research essay was published in a prestigious scientific journal, which highlights her groundbreaking research findings.","t":"她的研究論文被發表在一本著名的科學雜誌中，這彰顯了她的開創性研究成果。"},{"w":"journal","p":"n.","d":"","c":"日記","s":"She faithfully wrote in her journal every night, which documents her thoughts and experiences.","t":"她每晚都忠實地寫下她的日記，記錄下她的思想和經歷。"},{"w":"journalist","p":"n.","d":"","c":"新聞記者；記者","s":"The journalist uncovered corruption within the government, which led to a national scandal.","t":"記者揭露了政府內部的腐敗行為，這引發了一場全國性的醜聞。"},{"w":"keep a journal","p":"phr.","d":"","c":"寫日誌、記錄心得","s":"During his travels across Asia, he decided to keep a journal to capture his daily thoughts and experiences.","t":"在他橫跨亞洲的旅行中，他決定寫日誌來記錄每天的想法與經驗。"},{"w":"keep a diary","p":"phr.","d":"","c":"寫日記 (通常較私密)","s":"She has been keeping a diary since she was ten years old, writing in it every night before bed.","t":"她從十歲起就一直寫日記，每晚睡前都會在裡面寫字。"},{"w":"journalism","p":"n.","d":"","c":"新聞業、新聞工作","s":"He decided to study journalism at university because he wanted to report on international conflicts.","t":"他決定在大學攻讀新聞學，因為他想報導國際衝突。"},{"w":"sensational journalism","p":"phr.","d":"","c":"煽情新聞、八卦新聞","s":"Many critics argue that sensational journalism focuses too much on scandals rather than important social issues.","t":"許多評論家認為，煽情新聞過度關注醜聞，而非重要的社會議題。"},{"w":"suggest","p":"v.","d":"","c":"建議；提議","s":"She suggested that a few changes to the project (should) be made to make it more efficient and cost-effective.","t":"她提議對項目計劃進行一些修改，以使其更加高效和具有成本效益。"},{"w":"suggestion","p":"n.","d":"","c":"建議；提議","s":"He made a suggestion to improve office productivity, and his suggestion was accepted by the team members.","t":"他提出一個提高辦公室生產力的建議被團隊成員接受。"},{"w":"suggest","p":"v.","d":"","c":"暗示、顯示、建議","s":"The dark clouds in the sky suggest that a heavy storm is approaching.","t":"天上的烏雲暗示著一場強烈的風暴即將來臨。"},{"w":"suggestion","p":"n.","d":"","c":"暗示、建議","s":"There was a slight suggestion of disappointment in her voice, even though she tried to smile to cover her neagtive emotion.","t":"她的聲音中仍帶有一絲失望的暗示，儘管她試著微笑去掩飾他的負面情緒。"},{"w":"relation","p":"n.","d":"","c":"關聯性","s":"The relation between these two events is not immediately clear, but further investigation may reveal a connection.","t":"這兩個事件之間的關係並不立即清楚，但進一步的調查可能會揭示一種聯繫。"},{"w":"relationship","p":"n.","d":"","c":"關係；關聯","s":"He has built a close relationship with his teammates, which helps them overcome numerous challenges in life.","t":"他和隊友建立起了密切的關係，這幫助他們克服了生活中的眾多挑戰。"},{"w":"relative","p":"adj.","d":"","c":"相對的；相關的","s":"The relative humidity in this region makes it a comfortable place to live.","t":"這個地區的相對濕度使其成為一個舒適的居住地。"},{"w":"relative","p":"n.","d":"","c":"親戚；相關的人或事物","s":"Many relatives came to the family reunion, including my cousins, aunts, and uncles.","t":"許多親戚參加了家庭團聚，包括表兄弟、姑姑和叔叔。"},{"w":"be related to","p":"phr.","d":"","c":"與...有關；與...有親戚關係","s":"The discovery of the ancient artifact may be related to the history of this region.","t":"這個古代文物的發現可能與這個地區的歷史有關。"},{"w":"be associated with","p":"phr.","d":"","c":"與...有關聯","s":"Many health risks are associated with smoking, including heart disease and various types of cancer.","t":"許多健康風險與吸菸有關聯，包括心臟病和各類癌症。"},{"w":"be connected to/with","p":"phr.","d":"","c":"與...有連結/關係","s":"The detective found evidence that the suspect might be connected to the local criminal gang.","t":"偵探發現證據顯示嫌犯可能與當地的犯罪集團有關係。 偵探發現證據顯示嫌犯可能與當地的犯罪集團有關係。"},{"w":"research","p":"n.","d":"","c":"研究；調查","s":"The research (which is) conducted by the team requires months of data collection and analysis to draw meaningful conclusions.","t":"團隊進行的研究需要數月的數據收集和分析，以得出有意義的結論。"},{"w":"researcher","p":"n.","d":"","c":"研究人員；調查者","s":"The researcher was awarded a grant to further investigate the effects of climate change on the local ecosystem.","t":"研究人員獲得了一筆資助金，以進一步研究氣候變化對當地生態系統的影響。"},{"w":"suspect","p":"v.","d":"","c":"懷疑；猜想","s":"The detective began to suspect foul play when he noticed inconsistencies in the witness's statement.","t":"探長開始懷疑有不正當行為，當他注意到證人的陳述中存在不一致之處。"},{"w":"suspect","p":"n.","d":"","c":"嫌疑犯；可疑者","s":"The police questioned the suspect but didn't have enough evidence to arrest him or charge him of any crime.","t":"警方盤問了這名嫌疑犯，但沒有足夠的證據進行逮捕或起訴他任何罪刑。"},{"w":"discovery","p":"n.","d":"","c":"發現；發現物","s":"The discovery of a rare fossil in the desert was a significant breakthrough in biology.","t":"在沙漠中發現一個罕見的化石在古生物學上是一個重大的突破。"},{"w":"discover","p":"v.","d":"","c":"發現；找到","s":"In the comic One Piece, the explorer is determined to discover a hidden treasure (which is) rumored to be buried on the island.","t":"在海賊王這個漫畫中，這位探險家決心要發現據說埋藏在這個島上的隱藏寶藏。"},{"w":"confirm","p":"v.","d":"","c":"確認；證實","s":"The lab results confirmed that the patient had a rare genetic condition.","t":"實驗室的結果證實了患者患有一種罕見的遺傳病。"},{"w":"confirmation","p":"n.","d":"","c":"確認；證實","s":"The official confirmation of the election results brought an end to the months-long uncertainty.","t":"選舉結果的官方確認結束了長達數月的不確定性。"},{"w":"arise","p":"v.","d":"","c":"出現；發生","s":"Unexpected challenges can arise during a complex project, which requires quick problem-solving.","t":"在複雜的企劃案中，意想不到的挑戰可能會出現，需要快速解決問題。"},{"w":"arise from","p":"phr.","d":"","c":"由...引起；起源於...=result from","s":"Many environmental problems arise from human activities and industrialization.","t":"許多環境問題起源於人類活動和工業化。"},{"w":"attract","p":"v.","d":"","c":"吸引；引起興趣","s":"The colorful artworks on display at the gallery are designed to attract visitors and spark their curiosity.","t":"畫廊展示的多彩藝術品旨在吸引訪客，激發他們的好奇心。"},{"w":"attraction","p":"n.","d":"","c":"吸引；吸引力","s":"The famous theme park is a major tourist attraction, which draws visitors from around the world.","t":"這個著名的主題公園是一個主要的旅遊景點，吸引來自世界各地的遊客。"},{"w":"attractive","p":"adj.","d":"","c":"有吸引力的；迷人的","s":"Her attractive smile and friendly personality made her instantly likable to everyone she met.","t":"她迷人的微笑和友好的個性使她在遇到的每個人中都受歡迎。"},{"w":"tourist attraction","p":"phr.","d":"","c":"觀光景點","s":"The Eiffel Tower is a world-famous tourist attraction that draws millions of visitors to Paris every year.","t":"艾菲爾鐵塔是一個世界聞名的觀光景點，每年吸引數百萬遊客來到巴黎。"},{"w":"tourist destination","p":"phr.","d":"","c":"觀光勝地、目的地","s":"Taiwan has become a popular tourist destination for food lovers, thanks to its vibrant night markets.","t":"台灣已成為深受美食愛好者歡迎的觀光勝地，這要歸功於其充滿活力的夜市。"},{"w":"scenic spot","p":"phr.","d":"","c":"風景區、景點","s":"Sun Moon Lake is a beautiful scenic spot known for its breathtaking views and calm waters.","t":"日月潭是一個美麗的風景區，以其壯麗的景色和平靜的湖水聞名。"},{"w":"rapid","p":"adj.","d":"","c":"迅速的；快速的","s":"The rapid growth of the tech industry has led to a high demand for skilled professionals.","t":"科技行業的迅速增長導致了對熟練專業人士的高需求。"},{"w":"reduce","p":"v.","d":"","c":"減少；降低","s":"To reduce energy consumption, it's essential to use energy-efficient appliances and practices.","t":"為了減少能源消耗，使用節能電器和做法很重要。"},{"w":"reduction in...","p":"n.","d":"","c":"減少；降低","s":"The government's policy has led to a significant reduction in greenhouse gas emissions, which was a significant environmental achievement.","t":"政府的政策導致了溫室氣體排放大幅減少，這是一個重大的環境成就。"},{"w":"increase","p":"v.","d":"","c":"增加；提高","s":"To meet the growing demand, the company has decided to increase production capacity by investing in new equipment.","t":"為了滿足不斷增長的需求，該公司決定藉由投資新設備來增加生產能力。"},{"w":"the increase in","p":"n.","d":"","c":"增加；提高","s":"The increase in sales revenue was a positive sign for the company's financial health.","t":"銷售收入的增加是公司財務健康的一個積極信號。"},{"w":"increasing","p":"adj.","d":"","c":"增加的；不斷增加的","s":"The increasing demand for renewable energy sources is driving innovation in the green technology sector.","t":"對可再生能源的不斷增加的需求推動了綠色技術行業的創新。"}]},{"unit":6,"theme":"fake – be suspicious of","cards":[{"w":"fake","p":"adj.","d":"","c":"假的","s":"She bought a fake designer bag of a luxury brand, only to find that it is a counterfeit.","t":"她買了一個假的豪華品牌設計師包，只發現它是個仿冒品。"},{"w":"mislead","p":"v.","d":"","c":"誤導","s":"The false advertising can mislead consumers into making uninformed decisions about the product.","t":"虛假廣告可能會誤導消費者，使他們對產品做出不知情的決策。"},{"w":"misleading","p":"adj.","d":"","c":"誤導的","s":"The brochure contained misleading information, causing confusion among potential customers.","t":"這本手冊包含了誤導性資訊，引起了潛在客戶的混淆。"},{"w":"customer","p":"n.","d":"","c":"顧客","s":"The store values its customer feedback and takes it into account when making improvements.","t":"這家店重視顧客的反饋，並在進行改進時考慮其中的意見。"},{"w":"except","p":"n.","d":"","c":"除了...之外","s":"Everyone attended the meeting except for John, who was unable to make it due to illness.","t":"除了約翰，每個人都參加了會議，由於生病他無法參加。"},{"w":"exception","p":"n.","d":"","c":"例外","s":"There is an exception to the rule, but it rarely applies in practice.","t":"這個規則有一個例外，但在實踐中很少適用。"},{"w":"no exception","p":"phr.","d":"","c":"不例外","s":"Everyone must follow the school rules, and the senior students are no exception.","t":"每個人都必須遵守校規，高年級學生也不例外。"},{"w":"exceptional","p":"adj.","d":"","c":"卓越的、傑出的；異常的","s":"Her exceptional talent for music was recognized by the judges, who awarded her the first prize.","t":"她卓越的音樂天賦得到了評審的認可，並授予她一等獎。"},{"w":"achieve","p":"v.","d":"","c":"實現","s":"She worked tirelessly to achieve her goals, dedicating long hours to her studies and projects.","t":"她不知疲倦地努力工作以實現她的目標，她花費了很多時間在學習和項目上。"},{"w":"achievement","p":"n.","d":"","c":"成就","s":"Winning the competition was a great achievement for the team, and they celebrated their success enthusiastically.","t":"贏得比賽對於團隊來說是一個巨大的成就，他們熱情慶祝他們的成功。"},{"w":"a sense of achievement","p":"phr.","d":"","c":"成就感","s":"Completing the difficult project on time gave the entire team a huge a sense of achievement.","t":"準時完成這項困難的專案讓整個團隊獲得了巨大的成就感。"},{"w":"high achiever","p":"phr.","d":"","c":"成功人士、高成就者","s":"As a high achiever, she always sets ambitious goals for herself and works tirelessly to reach them.","t":"作為一個高成就者，她總是為自己設定遠大的目標，並孜孜不倦地努力實現。"},{"w":"quality","p":"n.","d":"","c":"品質","s":"The company is known for its high quality products, which have earned them a loyal customer base.","t":"這家公司以其高品質的產品而聞名，這些產品為他們贏得了忠實的客戶基礎。"},{"w":"quantity","p":"n.","d":"","c":"數量","s":"We need to increase the quantity of production to meet the growing demand for our products.","t":"為了滿足對我們產品日益增長的需求，我們需要提高生產的數量。"},{"w":"industry","p":"n.","d":"","c":"行業","s":"The technology industry is constantly evolving, with new innovations and breakthroughs happening regularly.","t":"技術行業不斷發展變化，定期出現新的創新和突破。"},{"w":"industrial","p":"adj.","d":"","c":"工業的","s":"Pollution is a common issue in industrial areas, posing a threat to both the environment and human health.","t":"污染在工業區是一個常見問題，對環境和人類健康都構成威脅。"},{"w":"the Industrial Revolution","p":"phr.","d":"","c":"工業革命","s":"The Industrial Revolution began in the 18th century and completely changed the way goods were produced and people lived.","t":"工業革命始於 18 世紀，徹底改變了商品的生產方式以及人們的生活方式。"},{"w":"industrial restructure","p":"phr.","d":"","c":"產業結構調整","s":"To stay competitive in the global market, the government is planning an industrial restructure to move from manufacturing to services.","t":"為了在全球市場保持競爭力，政府正計畫進行產業結構調整，從製造業轉向服務業。"},{"w":"industrial upgrade","p":"phr.","d":"","c":"產業升級","s":"Digital transformation and automation are key factors in achieving an industrial upgrade for traditional factories.","t":"數位轉型與自動化是傳統工廠實現產業升級的關鍵因素。"},{"w":"require","p":"v.","d":"","c":"需要","s":"This job will require a lot of hard work and dedication, as it involves complex tasks and responsibilities.","t":"這份工作需要付出大量的努力和奉獻，因為它涉及到複雜的任務和責任。"},{"w":"required","p":"adj.","d":"","c":"必需的","s":"Safety equipment is required for this task to ensure the well-being of the workers.","t":"這項任務需要安全設備，以確保工人的安全和福祉。"},{"w":"requirement","p":"n.","d":"","c":"要求","s":"Meeting the requirement is essential for the success of the project, and it sets clear standards for performance.","t":"符合這項要求對於項目的成功至關重要，它為性能設定了明確的標準。"},{"w":"rather than","p":"n.","d":"","c":"而不是(前後同詞性)","s":"She would travel within the country rather than take a plane abroad because she feels frightened to travel by plane.","t":"她寧願在國內旅行也不願搭飛機出國，因為她害怕搭飛機旅行。"},{"w":"instead of","p":"phr.","d":"","c":"而不是+ n/Ving","s":"He bought an e-book instead of a physical one, finding it more convenient for his travels.","t":"他購買了電子書而不是實體書，認為它更適合他的旅行。"},{"w":"substance","p":"n.","d":"","c":"物質","s":"Scientists are researching the mysterious substance found in the meteorite to understand its origin.","t":"科學家正在研究在隕石中發現的神秘物質，以了解其起源。"},{"w":"substantial","p":"adj.","d":"","c":"大量的、實質的、重大的","s":"The company reported a substantial increase in profits this year, thanks to the successful launch of its new product.","t":"由於新產品的成功上市，該公司報告今年利潤有了實質性的增長。"},{"w":"chemical","p":"n.","d":"","c":"化學製品、化學物質","s":"Farmers are encouraged to use natural fertilizers instead of harsh chemicals to protect the environment.","t":"鼓勵農民使用天然肥料代替劇烈的化學物質，以保護環境。"},{"w":"material","p":"n.","d":"","c":"材料、原料、資料","s":"The students spent the afternoon gathering materials for their science project in the library.","t":"學生們下午在圖書館收集科學專案所需的資料。"},{"w":"building material","p":"phr.","d":"","c":"建築材料","s":"Steel and concrete are the most common building materials used in the construction of modern skyscrapers.","t":"鋼鐵和混凝土是現代摩天大樓建築中最常用的建築材料。"},{"w":"ingredient","p":"n.","d":"","c":"(烹調的) 原料、成分、要素","s":"Flour, eggs, and sugar are the three basic ingredients needed to bake a simple sponge cake.","t":"麵粉、雞蛋和糖是烘焙簡單海綿蛋糕所需的三種基本原料。"},{"w":"is linked to","p":"phr.","d":"","c":"連接到","s":"Studies have shown that regular exercise is linked to better mental health, reducing symptoms of anxiety and depression.","t":"研究表明，定期運動可以連接到更好的心理健康，減少焦慮和抑鬱的症狀。"},{"w":"be associated with","p":"phr.","d":"","c":"與...有關聯 (偏邏輯/特質)","s":"High stress levels are associated with an increased risk of heart disease and other health problems.","t":"高壓與心臟病及其他健康問題的風險增加有關聯。"},{"w":"be related to","p":"phr.","d":"","c":"與...有關 (範圍最廣/血緣)","s":"The increase in crime in this area might be related to the rising unemployment rate.","t":"該地區犯罪率的增加可能與不斷上升的失業率有關。"},{"w":"be connected to","p":"phr.","d":"","c":"與...有連結 (偏實體/直接)","s":"The detective discovered that the suspect is connected to a series of robberies across the city.","t":"偵探發現嫌犯與城市裡的一系列搶劫案有關連。"},{"w":"cancer","p":"n.","d":"","c":"癌症","s":"Due to his family history, he regularly undergoes checks for cancer to ensure early detection.","t":"由於他的家族病史，他定期進行癌症檢查以確保早期發現。"},{"w":"metal","p":"n.","d":"","c":"金屬","s":"The artist uses scrap metal to create sculptures that convey messages about environmental conservation.","t":"藝術家使用廢金屬創作雕塑，傳達有關環境保護的信息。"},{"w":"exhibit","p":"v.","d":"","c":"展示","s":"The museum will exhibit ancient artifacts from various civilizations next month.","t":"博物館將於下個月展出來自各個文明的古代文物。"},{"w":"visible","p":"adj.","d":"","c":"可見的","s":"After the rain, a beautiful rainbow became visible in the sky, attracting many onlookers.","t":"雨後，天空中出現了美麗的彩虹，吸引了許多觀眾。"},{"w":"invisible","p":"adj.","d":"","c":"看不見的","s":"Even though it's invisible to the naked eye, microscopic bacteria play a crucial role in our ecosystem.","t":"儘管肉眼看不見，但微小的細菌在我們的生態系統中起著至關重要的作用。"},{"w":"medical","p":"adj.","d":"","c":"醫療的","s":"After his accident, he received medical attention immediately to prevent any complications.","t":"他出事故後立即得到了醫療照顧，以防止任何併發症。"},{"w":"condition","p":"n.","d":"","c":"狀況","s":"The old building is in poor condition and requires extensive repairs before it can be inhabited again.","t":"這座老建築物狀況不佳，需要進行大量維修才能再次入住。"},{"w":"in good condition","p":"phr.","d":"","c":"狀況良好","s":"Although the car is over ten years old, it is still in good condition because the owner maintained it carefully.","t":"雖然這輛車已經超過十年了，但因為車主精心保養，它依然狀況良好。"},{"w":"in a dire condition","p":"phr.","d":"","c":"處於極其惡劣/危急的處境","s":"After the war, the country's economy was in a dire condition, with high unemployment and severe food shortages.","t":"戰爭結束後，該國的經濟處於極其惡劣的境地，失業率高且糧食嚴重短缺。"},{"w":"in the terminal condition","p":"phr.","d":"","c":"處於末期狀態 (病入膏肓)","s":"When a patient is in the terminal condition, the focus of medical care often shifts from cure to comfort and pain relief.","t":"當病人處於末期狀態時，醫療護理的重心通常會從治療轉向舒適與緩解疼痛。"},{"w":"disease","p":"n.","d":"","c":"疾病","s":"Scientists are working tirelessly to find a cure for the disease that has affected millions worldwide.","t":"科學家正在不懈地尋找治療這種影響全球數百萬人的疾病的方法。"},{"w":"chronic disease","p":"phr.","d":"","c":"慢性病","s":"High blood pressure and diabetes are common chronic diseases that require long-term medical management.","t":"高血壓和糖尿病是常見的慢性病，需要長期的醫療管理。"},{"w":"be suspicious of","p":"phr.","d":"","c":"懷疑","s":"She began to be suspicious of his actions when he returned home late every night without a clear explanation.","t":"當他每晚回家都很晚而沒有明確的解釋時，她開始懷疑他的行為。"}]},{"unit":7,"theme":"consider – scented","cards":[{"w":"consider","p":"v.","d":"to think carefully about something before making a decision.","c":"考慮","s":"It is essential to consider both the advantages and disadvantages before making a decision that will impact the entire organization.","t":"在對整個組織產生影響的決策之前，考慮到利弊是至關重要的。"},{"w":"considerable","p":"adj.","d":"large enough in amount, size, or importance to be noticed.","c":"相當大的","s":"The project required a considerable amount of time and resources to complete, but the results were worth the effort.","t":"這個項目需要大量的時間和資源才能完成，但結果是值得的。"},{"w":"considerate","p":"adj.","d":"kind and careful not to upset or inconvenience others.","c":"體貼的","s":"Sarah is known for her considerate nature, always thinking of others and making sure everyone feels comfortable and cared for.","t":"莎拉以她的體貼天性而聞名，總是關心他人，確保每個人感到舒適和關愛。"},{"w":"take into consideration","p":"phr.","d":"to think about a fact or situation when making a decision.","c":"考慮到","s":"When planning the event, we need to take into consideration all potential challenges and unforeseen circumstances to ensure its success.","t":"在計劃活動時，我們需要考慮到所有可能的挑戰和意想不到的情況，以確保其成功。"},{"w":"stranger","p":"n.","d":"a person whom you do not know.","c":"陌生人","s":"She approached the stranger and struck up a conversation, turning a chance encounter into a meaningful connection.","t":"她走近那個陌生人，開始了一次交談，將一次偶然的相遇變成了一次有意義的聯繫。"},{"w":"parade","p":"v.","d":"to walk or march in a public celebration or display.","c":"遊行","s":"The city will parade down the main street to celebrate the national holiday, with colorful floats and marching bands.","t":"城市將沿主要街道遊行，慶祝國慶日，有多彩的花車和行進樂隊。"},{"w":"parade","p":"n.","d":"a public celebration in which people, vehicles, or performers move along a street.","c":"遊行","s":"The annual Thanksgiving parade attracts thousands of spectators who line the streets to enjoy the festive atmosphere.","t":"每年的感恩節遊行吸引了成千上萬的觀眾，他們在街頭欣賞著節日氛圍。"},{"w":"cheer","p":"v.","d":"to shout loudly to show support or happiness.","c":"歡呼","s":"Fans began to cheer loudly when their team scored the winning goal in the final minutes of the game.","t":"當球隊在比賽最後幾分鐘踢進致勝球時，球迷開始大聲歡呼。"},{"w":"cheer","p":"n.","d":"a shout of happiness, praise, or encouragement.","c":"歡呼","s":"The cheer and applause filled the stadium, creating an electric atmosphere as the athletes crossed the finish line.","t":"歡呼和掌聲充滿了體育場，當運動員越過終點線時，營造出一種充滿活力的氛圍。"},{"w":"cheer up","p":"phr.","d":"to become happier or make someone feel happier.","c":"高興起來；振作起來","s":"After a tough week, Sarah's friends decided to throw her a surprise party to cheer her up and bring a smile to her face.","t":"經過艱難的一周後，莎拉的朋友們決定為她舉辦一個驚喜派對，讓她振作起來並露出笑容。"},{"w":"cheerful","p":"adj.","d":"happy and positive.","c":"快樂的","s":"Emily's cheerful disposition brightened the room, and her laughter was contagious, spreading joy to everyone around her.","t":"艾米莉快樂的性格照亮了整個房間，她的笑聲很有感染力，把快樂傳給周圍的人。"},{"w":"splash","p":"v.","d":"to make liquid fly or fall in drops.","c":"濺潑","s":"The kids decided to splash in the puddles after the rain, enjoying the simple pleasure of getting wet and dirty.","t":"孩子們決定在雨後的水坑裡濺水，享受弄濕和弄髒的簡單樂趣。"},{"w":"good-natured","p":"adj.","d":"friendly, patient, and pleasant.","c":"好性格的","s":"John's good-natured personality made him a favorite among his coworkers, as he was always ready to lend a helping hand and offer a smile.","t":"約翰的好性格使他成為同事們喜愛的人，因為他總是樂於伸出援手並獻上微笑。"},{"w":"kind-hearted","p":"adj.","d":"kind and generous toward other people or animals.","c":"善良的","s":"Maria's kind-hearted nature led her to volunteer at the local animal shelter, where she cared for abandoned pets.","t":"瑪麗亞的善良天性使她成為當地動物收容所的志願者，在那裡照顧被遺棄的寵物。"},{"w":"ill-tempered","p":"adj.","d":"easily annoyed or made angry.","c":"易怒的","s":"His ill-tempered outbursts often strained his relationships with others, as people found it challenging to be around him when he was in a bad mood.","t":"他易怒的爆發經常破壞他與他人的關係，因為人們發現他心情不好時很難相處。"},{"w":"old-fashioned","p":"adj.","d":"not modern; belonging to or typical of the past.","c":"過時的","s":"Sarah's grandparents had an old-fashioned record player that they still used to listen to classic vinyl records.","t":"莎拉的祖父母有一台過時的唱片機，他們仍用它來聽經典黑膠唱片。"},{"w":"left-handed","p":"adj.","d":"using the left hand more naturally than the right hand.","c":"左撇子的","s":"Being left-handed in a predominantly right-handed world can sometimes present challenges, but many people excel in various fields.","t":"在主要是右撇子的世界中，左撇子有時可能面臨挑戰，但許多人在各領域都表現出色。"},{"w":"in one's spare time","p":"phr.","d":"during time when one is not working or busy.","c":"在某人的空閒時間","s":"In her spare time, Jane enjoys reading novels, practicing yoga, and exploring new hiking trails in the mountains.","t":"在她的空閒時間，珍妮喜歡閱讀小說、練習瑜伽，並探索山區的新徒步步道。"},{"w":"spare from","p":"phr.","d":"to prevent someone from having to experience something unpleasant or unnecessary.","c":"使免於；使省去","s":"This shortcut can spare you from long delays during the morning commute.","t":"這條捷徑可以使人免於早晨通勤時的長時間延誤。"},{"w":"spare","p":"adj.","d":"extra and available to use when needed.","c":"多餘的；備用的","s":"He had a spare ticket to the concert and offered it to a friend who had missed out on buying one.","t":"他有一張多餘的音樂會門票，把它提供給一位沒買到票的朋友。"},{"w":"spare","p":"n.","d":"an extra item kept for use if needed.","c":"備用品","s":"It is always a good idea to carry a spare umbrella in case of unexpected rain while you are out and about.","t":"在外出時隨身攜帶一把備用雨傘以應對突然下雨，是一個好主意。"},{"w":"respect","p":"v.","d":"to treat someone or something as important and valuable.","c":"尊重","s":"It is important to respect the opinions and beliefs of others, even if they differ from your own.","t":"尊重他人的意見和信仰很重要，即使它們與你自己的不同。"},{"w":"respect","p":"n.","d":"admiration or polite treatment for someone or something.","c":"尊重","s":"Mutual respect in a relationship is the foundation of trust and understanding between partners.","t":"一段關係中的相互尊重是伴侶之間建立信任和理解的基礎。"},{"w":"respectful","p":"adj.","d":"showing politeness and respect.","c":"尊重的","s":"Sarah's respectful demeanor toward her colleagues created a harmonious work environment where everyone felt valued.","t":"莎拉對同事們的尊重態度創造了一個和諧的工作環境，每個人都感到受到重視。"},{"w":"respectable","p":"adj.","d":"considered good, proper, or worthy of respect.","c":"值得尊敬的","s":"His dedication to charity work and his contributions to the community earned him a respectable reputation.","t":"他對慈善工作的奉獻以及對社區的貢獻，使他贏得了值得尊敬的聲譽。"},{"w":"respective","p":"adj.","d":"belonging separately to each of the people or things already mentioned.","c":"各自的；分別的","s":"The team members presented their respective findings from the research, highlighting their individual contributions.","t":"團隊成員展示了他們在研究中的各自結果，突出了他們的個別貢獻。"},{"w":"respected","p":"adj.","d":"admired by many people because of achievements or character.","c":"受尊敬的","s":"The professor was highly respected in the academic community for his groundbreaking research and contributions to physics.","t":"這位教授因在物理學領域的開創性研究和貢獻而在學術界受到高度尊敬。"},{"w":"pour","p":"v.","d":"to make a liquid flow from one container into another.","c":"倒","s":"She decided to pour a glass of cold water to quench her thirst after spending hours in the scorching sun.","t":"在烈日下待了幾個小時後，她決定倒一杯冷水解渴。"},{"w":"tourism","p":"n.","d":"the business or activity of people traveling for pleasure.","c":"旅遊","s":"Tourism plays a significant role in the economy of many countries, attracting visitors from around the world and generating revenue.","t":"旅遊在許多國家的經濟中扮演重要角色，吸引世界各地的遊客並產生收入。"},{"w":"tourist","p":"n.","d":"a person who travels to a place for pleasure.","c":"遊客","s":"The city welcomed a record number of tourists last year, with people coming to explore its cultural heritage and natural beauty.","t":"這座城市去年迎來了創紀錄的遊客數量，人們前來探索它的文化遺產和自然之美。"},{"w":"tourist attraction","p":"n.","d":"a place that many travelers visit because it is interesting or enjoyable.","c":"旅遊景點","s":"The ancient castle has become a major tourist attraction, drawing visitors from all over the world.","t":"這座古堡已成為一個主要的旅遊景點，吸引世界各地的遊客。"},{"w":"favorite","p":"adj.","d":"liked best.","c":"最喜愛的","s":"Her favorite book is a classic novel that she reads every year.","t":"她最喜愛的書是一部她每年都會讀的經典小說。"},{"w":"target","p":"n.","d":"a goal or result that someone is trying to achieve.","c":"目標","s":"The company set a target of doubling its sales by the end of the year.","t":"公司設定了在年底前將銷售額增加一倍的目標。"},{"w":"target","p":"v.","d":"to aim an action, product, or message at a particular person or group.","c":"以……為目標","s":"The new marketing campaign was designed to target younger consumers.","t":"新的營銷活動旨在以年輕消費者為目標。"},{"w":"aim at","p":"phr.","d":"to be intended for a particular purpose, person, or group.","c":"以……為目標","s":"The educational program is aimed at providing skills training for recent graduates.","t":"這個教育計劃旨在為新近畢業生提供技能培訓。"},{"w":"aim to","p":"phr.","d":"to intend or plan to do something.","c":"旨在","s":"The charity will aim to alleviate poverty in rural communities.","t":"這個慈善機構旨在減輕農村社區的貧困。"},{"w":"reach a goal","p":"phr.","d":"to successfully achieve something one has been trying to do.","c":"達成目標","s":"With dedication and hard work, she was able to reach her goal of becoming a doctor.","t":"通過奉獻和努力工作，她能夠達成成為醫生的目標。"},{"w":"community","p":"n.","d":"a group of people who live in the same area or share something in common.","c":"社區","s":"The new park has greatly improved the sense of community in our neighborhood.","t":"新公園極大地提升了我們社區的社區感。"},{"w":"A sense of community","p":"phr.","d":"a feeling of belonging and connection with others in a group or area.","c":"社區感","s":"Volunteering at the local shelter helped him develop a sense of community with others in the area.","t":"在當地避難所做義工幫助他與該地區的其他人建立了社區感。"},{"w":"scented","p":"adj.","d":"having a pleasant smell.","c":"有香味的","s":"She loves lighting scented candles to create a relaxing atmosphere at home.","t":"她喜歡點燃有香味的蠟燭，營造家中的放鬆氛圍。"}]},{"unit":8,"theme":"efficient – regulate","cards":[{"w":"efficient","p":"adj.","d":"effective and able to produce good results without wasting time or resources.","c":"有效的","s":"The new production process is much more efficient, allowing us to manufacture products faster and with fewer resources.","t":"新的生產過程更加有效，使我們能夠更快速地製造產品並使用更少的資源。"},{"w":"efficiency","p":"n.","d":"the ability to do something well without wasting time or resources.","c":"效率","s":"The efficiency of our customer service department has improved significantly, resulting in shorter response times and happier customers.","t":"我們的客戶服務部門的效率有了顯著的提高，使反應時間縮短，客戶更加滿意。"},{"w":"object","p":"n.","d":"a thing that can be seen or touched.","c":"物體","s":"The museum features a wide range of historical objects, including ancient artifacts and artworks.","t":"博物館展示了各種歷史物體，包括古代文物和藝術品。"},{"w":"object to","p":"v.","d":"to disagree with or oppose something.","c":"反對","s":"Some employees may object to the new policy, but it was implemented to improve workplace safety.","t":"一些員工可能會反對新政策，但它是為了提高工作場所的安全性而實施的。"},{"w":"objective","p":"n.","d":"a goal or purpose that someone is trying to achieve.","c":"目標","s":"The main objective of the project is to reduce energy consumption and minimize environmental impact.","t":"該項目的主要目標是減少能源消耗並最小化環境影響。"},{"w":"objective","p":"adj.","d":"based on facts rather than feelings or personal opinions.","c":"客觀的","s":"The report provides an objective analysis of the current market conditions, free from personal bias.","t":"這份報告對當前的市場狀況進行了客觀分析，不帶個人偏見。"},{"w":"delay","p":"n.","d":"a period of waiting or being late.","c":"延遲","s":"The delay in the delivery of materials has caused a setback in the construction project schedule.","t":"材料交付的延遲導致了建設項目進度的挫折。"},{"w":"delay","p":"v.","d":"to make something happen later than expected.","c":"延遲","s":"Bad weather conditions may delay our flight, so please check for updates at the airport.","t":"惡劣的天氣條件可能會延遲我們的航班，請在機場查看最新信息。"},{"w":"buzz","p":"n.","d":"a low continuous sound, like the sound of many people talking or insects flying.","c":"嗡嗡聲","s":"The buzz of conversation filled the room as guests mingled and shared stories during the party.","t":"在派對上，客人們交往並分享故事，嗡嗡聲充滿了整個房間。"},{"w":"buzz","p":"v.","d":"to make a low continuous sound.","c":"嗡嗡作響","s":"Bees buzz around the flowers, collecting nectar for their hive.","t":"蜜蜂在花朵周圍嗡嗡作響，收集花蜜回巢。"},{"w":"period","p":"n.","d":"a length of time with a beginning and an end.","c":"時期","s":"The Renaissance was a period of great cultural and artistic achievements in Europe.","t":"文藝復興時期是歐洲文化和藝術偉大成就的時期。"},{"w":"A period of time","p":"phr.","d":"an amount or stretch of time.","c":"一段時間","s":"She spent a period of time traveling through Asia, exploring diverse cultures and cuisines.","t":"她花了一段時間在亞洲旅行，探索多元文化和美食。"},{"w":"periodical","p":"n.","d":"a magazine or journal that is published regularly.","c":"期刊","s":"He reads a monthly periodical to stay updated on the latest scientific research and discoveries.","t":"他閱讀一份月刊，以便隨時獲取最新的科學研究和發現信息。"},{"w":"extend","p":"v.","d":"to make something longer, larger, or wider in area or influence.","c":"延伸；擴展","s":"The company plans to extend its operations to international markets in the coming year.","t":"公司計劃在未來一年擴展其國際市場業務。"},{"w":"extended","p":"adj.","d":"made longer in time or space.","c":"延長的","s":"Due to the extended winter weather, the school decided to extend the holiday break by one week.","t":"由於漫長的冬季天氣，學校決定將假期延長一週。"},{"w":"extensive","p":"adj.","d":"covering a large area, amount, or range.","c":"廣泛的","s":"Her extensive knowledge of history allowed her to teach a wide range of historical topics.","t":"她廣泛的歷史知識使她能夠教授各種歷史主題。"},{"w":"extensive reading","p":"n.","d":"reading a lot of material for general understanding and language growth.","c":"泛讀","s":"Extensive reading is an effective way to improve language skills and gain exposure to various writing styles.","t":"泛讀是提高語言技能並接觸各種寫作風格的有效方式。"},{"w":"extension","p":"n.","d":"an addition that makes something larger or longer.","c":"擴展","s":"The company is planning an extension of its product line to include more eco-friendly options.","t":"公司計劃擴展其產品線，包括更多環保選擇。"},{"w":"improve","p":"v.","d":"to make something better.","c":"改進","s":"Regular practice can help you improve your skills and become more proficient in any area.","t":"定期練習可以幫助你改進你的技能，並在任何領域變得更加熟練。"},{"w":"improvement","p":"n.","d":"a change that makes something better.","c":"改進；改善","s":"The recent improvement in our manufacturing process has resulted in higher product quality and customer satisfaction.","t":"我們最近在製造過程中的改進使產品質量提高，客戶滿意度提高。"},{"w":"make improvements","p":"phr.","d":"to make changes that improve something.","c":"作出改進","s":"The company is always looking for ways to make improvements in its products and services.","t":"公司始終尋找在其產品和服務中作出改進的方法。"},{"w":"system","p":"n.","d":"a set of connected parts that work together.","c":"系統","s":"The new operating system is designed to streamline processes and improve overall efficiency.","t":"新的操作系統旨在簡化流程並提高整體效率。"},{"w":"the immune system","p":"phr.","d":"the body system that protects against disease and infection.","c":"免疫系統","s":"A healthy lifestyle can strengthen the immune system and help the body fight off infections and illnesses.","t":"健康的生活方式可以增強免疫系統，幫助身體抵抗感染和疾病。"},{"w":"track","p":"n.","d":"a path or set of rails that a train or vehicle follows.","c":"軌道","s":"The train runs on a track that stretches for hundreds of miles, connecting cities across the country.","t":"火車行駛在數百英里長的軌道上，連接著全國各地的城市。"},{"w":"track","p":"v.","d":"to follow or record the progress or movement of something.","c":"追蹤","s":"It is important to track your expenses to ensure you stay within your budget each month.","t":"追蹤你的開支很重要，以確保每個月保持在預算內。"},{"w":"keep track of","p":"phr.","d":"to continue to know or record what is happening to someone or something.","c":"追蹤；掌握","s":"You should keep track of your progress in achieving your fitness goals by recording your workouts and diet.","t":"你應該通過記錄你的運動和飲食來追蹤實現健身目標的進展。"},{"w":"evaluate","p":"v.","d":"to judge or calculate the quality, importance, or value of something.","c":"評估","s":"The teacher will evaluate the students' performance based on their understanding of the subject matter and participation in class.","t":"老師將根據學生對科目的理解和課堂參與來評估他們的表現。"},{"w":"evaluation","p":"n.","d":"the act of judging the quality, importance, or value of something.","c":"評估","s":"The annual evaluation of employees helps the company identify areas for improvement and recognize outstanding contributions.","t":"員工的年度評估有助於公司識別改進的領域並表揚優秀的貢獻。"},{"w":"progress","p":"n.","d":"development or movement toward a better or more complete state.","c":"進展","s":"The project has made significant progress in recent months, and we are on track to meet our deadlines.","t":"該項目在最近幾個月取得了顯著的進展，我們正按計劃完成截止日期。"},{"w":"make progress on","p":"phr.","d":"to move forward or improve in work on something.","c":"在……上取得進展","s":"The team continues to make progress on the development of the new software, aiming for a flawless release.","t":"團隊繼續在新軟件的開發上取得進展，力爭推出無瑕疵的版本。"},{"w":"regulate","p":"v.","d":"to control something by rules or laws.","c":"規定；管制","s":"The government has implemented new policies to regulate the use of plastic bags in an effort to reduce environmental impact.","t":"政府已經實施了新政策，以規定使用塑料袋，以減少對環境的影響。"}]},{"unit":9,"theme":"arrival – launch","cards":[{"w":"arrival","p":"n.","d":"","c":"到達","s":"The arrival of the new manager was eagerly anticipated by the staff.","t":"員工們熱切期待著新經理的到來。"},{"w":"arrive in country/city","p":"phr.","d":"","c":"到達某國某城市","s":"She was excited to arrive in Paris for the first time.","t":"她很興奮第一次到達巴黎。"},{"w":"arrive at","p":"phr.","d":"","c":"到達某地","s":"After hours of driving, they finally arrived at their destination.","t":"經過幾小時的駕駛，他們終於到達了目的地。"},{"w":"the ...century","p":"n.","d":"","c":"世紀","s":"Many consider the 20th century to be one of the most eventful in history.","t":"許多人認為20世紀是歷史上最多事的一個世紀。"},{"w":"event","p":"n.","d":"","c":"事件","s":"The concert was the most talked-about event of the year.","t":"這場音樂會是一年中最受關注的事件。"},{"w":"release a hostage","p":"phr.","d":"","c":"釋放人質","s":"After negotiations, the kidnappers agreed to release the hostage.","t":"經過談判，綁架者同意釋放人質。"},{"w":"release a single/video/product","p":"phr.","d":"","c":"發行單曲/視頻/產品","s":"The artist is set to release a single next month.","t":"藝術家計劃下個月發行新單曲。"},{"w":"release exhaust","p":"phr.","d":"","c":"排放廢氣","s":"Factories that release exhaust into the atmosphere contribute to air pollution.","t":"向大氣中排放廢氣的工廠導致空氣污染。"},{"w":"release stress/ pressure","p":"phr.","d":"","c":"釋放壓力","s":"Meditation is a great way to release stress.","t":"冥想是釋放壓力的好方法。"},{"w":"release","p":"n.","d":"","c":"釋放","s":"The release of new information surprised everyone.","t":"新信息的釋放讓每個人都感到驚訝。"},{"w":"release","p":"n.","d":"","c":"發行","s":"The release of the new album was a huge success.","t":"新專輯的發行取得了巨大成功。"},{"w":"mobile","p":"adj.","d":"","c":"移動的","s":"With today's mobile technology, working remotely has become easier.","t":"隨著今天的移動技術，遠程工作變得更加容易。"},{"w":"mobile device / portable device","p":"n.","d":"","c":"行動裝置","s":"Many people use a mobile device for daily tasks like emailing, browsing the web, and managing schedules.","t":"許多人使用行動裝置來處理日常任務，如發送電子郵件、瀏覽網頁和管理日程。"},{"w":"mobility","p":"n.","d":"","c":"移動性","s":"The city's mobility options have been enhanced with new bike lanes.","t":"該市的移動性選項通過新的自行車道得到了提升。"},{"w":"automobile","p":"n.","d":"","c":"汽車","s":"The automobile industry has seen significant changes with the introduction of electric cars.","t":"隨著電動汽車的引入，汽車行業發生了重大變化。"},{"w":"attract","p":"v.","d":"","c":"吸引","s":"The bright colors of the flowers attract many bees and butterflies.","t":"花朵鮮豔的顏色吸引了許多蜜蜂和蝴蝶。"},{"w":"attraction","p":"n.","d":"","c":"吸引力","s":"The city's main attraction is its historic castle.","t":"這座城市的主要吸引力是它的歷史古堡。"},{"w":"tourist attraction","p":"phr.","d":"","c":"旅遊景點","s":"The Eiffel Tower is a famous tourist attraction in Paris.","t":"艾菲爾鐵塔是巴黎著名的旅遊景點。"},{"w":"attractive","p":"adj.","d":"","c":"有吸引力的","s":"The idea of a shorter workweek is attractive to many people.","t":"縮短工作周的想法對許多人來說很有吸引力。"},{"w":"appealing","p":"adj.","d":"","c":"吸引人的","s":"The concept of living a minimalist lifestyle is appealing to those who seek simplicity.","t":"對於追求簡約的人來說，過極簡生活方式的概念很吸引人。"},{"w":"fold","p":"v.","d":"","c":"折疊","s":"After reading the newspaper, he folded it and put it back on the table.","t":"閱讀報紙後，他將其折疊起來放回桌上。"},{"w":"fold","p":"n.","d":"","c":"折痕","s":"The fold in the paper indicates it has been in someone's pocket.","t":"紙上的折痕表明它曾放在某人的口袋裡。"},{"w":"folder","p":"n.","d":"","c":"文件夾","s":"She organized her documents into a folder for easy access.","t":"她將文件整理到一個文件夾中，以便輕鬆訪問。"},{"w":"foldable","p":"adj.","d":"","c":"可摺疊的","s":"The foldable bike can easily be stored in a small apartment.","t":"這款可摺疊自行車可以輕鬆存放在小公寓裡。"},{"w":"access","p":"v.","d":"","c":"存取","s":"Students can access the online library resources from anywhere.","t":"學生可以在任何地方存取線上圖書館資源。"},{"w":"access","p":"n.","d":"","c":"途徑","s":"The new road provides easier access to the remote village.","t":"新道路為到達偏遠村莊提供了更容易的途徑。"},{"w":"accessible","p":"adj.","d":"","c":"易接近的","s":"The museum is accessible to wheelchair users.","t":"這家博物館對輪椅使用者來說是易於進入的。"},{"w":"predictable","p":"adj.","d":"","c":"可預測的","s":"The outcome of the game was predictable based on the team's performance.","t":"根據球隊的表現，比賽的結果是可預測的。"},{"w":"available","p":"adj.","d":"","c":"可用的","s":"The new model will be available for purchase next month.","t":"新型號下個月將可供購買。"},{"w":"model","p":"n.","d":"","c":"模型","s":"The architect showed a model of the proposed building.","t":"建築師展示了擬建建築的模型。"},{"w":"model","p":"n.","d":"","c":"機號型號","s":"The latest model of the smartphone features several innovative upgrades.","t":"最新型號的智能手機具有多項創新升級。"},{"w":"model","p":"n.","d":"","c":"模特兒","s":"The fashion model walked down the runway with confidence.","t":"時尚模特兒充滿信心地走在伸展台上。"},{"w":"model","p":"v.","d":"","c":"模仿","s":"Young athletes often model their techniques after famous sports stars.","t":"年輕運動員經常模仿著名運動明星的技巧。"},{"w":"model","p":"v.","d":"","c":"穿戴衣服展示","s":"She will model the designer's new collection at the fashion show.","t":"她將在時裝秀上展示設計師的新系列。"},{"w":"portable","p":"adj.","d":"","c":"便攜的","s":"The portable charger is a convenient accessory for travelers.","t":"便攜式充電器是旅行者的方便配件。"},{"w":"portability","p":"n.","d":"","c":"便攜性","s":"The portability of the laptop makes it perfect for on-the-go use.","t":"筆記型電腦的便攜性使其非常適合在外使用。"},{"w":"importable","p":"adj.","d":"","c":"可進口的","s":"The company is looking for importable goods to expand its product range.","t":"該公司正在尋找可進口商品以擴展其產品範圍。"},{"w":"mass","p":"adj.","d":"","c":"大量的","s":"The mass production of goods has become a hallmark of modern industry.","t":"大量生產商品已成為現代工業的標誌。"},{"w":"mass production of goods","p":"phr.","d":"","c":"大量生產產品","s":"The Industrial Revolution led to mass production of goods, which has significantly lowered the cost of manufacturing.","t":"工業革命帶來產品的大量生產，這顯著降低了製造成本。"},{"w":"mass rapid transportation","p":"phr.","d":"","c":"大眾快速交通","s":"The city's mass rapid transportation system makes commuting easier for residents.","t":"該市的大眾快速交通系統使居民通勤更加容易。"},{"w":"mass media","p":"phr.","d":"","c":"大眾媒體","s":"Mass media plays a crucial role in shaping public opinion.","t":"大眾媒體在塑造公眾輿論中發揮著關鍵作用。"},{"w":"a mass of","p":"phr.","d":"","c":"大量的","s":"The museum houses a mass of rare artifacts.","t":"博物館收藏著大量稀有文物。"},{"w":"mass","p":"n.","d":"","c":"質量","s":"The mass of the planet is estimated to be six times that of Earth.","t":"該行星的質量估計是地球的六倍。"},{"w":"massive","p":"adj.","d":"","c":"巨大的","s":"The project requires a massive amount of resources and time.","t":"該項目需要大量的資源和時間。"},{"w":"production","p":"n.","d":"","c":"生產","s":"The factory's production levels have increased this year.","t":"工廠今年的生產水平有所提高。"},{"w":"produce","p":"v.","d":"","c":"生產","s":"The region is known to produce the finest quality of wine.","t":"該地區以生產最優質的葡萄酒而聞名。"},{"w":"produce","p":"n.","d":"","c":"農產品","s":"Fresh produce is sold at the local farmers' market.","t":"新鮮農產品在當地農民市場上出售。"},{"w":"productive","p":"adj.","d":"","c":"生產力強的","s":"The team had a very productive meeting and resolved many issues.","t":"團隊進行了非常有成效的會議，解決了許多問題。"},{"w":"productivity","p":"n.","d":"","c":"生產力","s":"Improved technology can significantly increase productivity.","t":"改進的技術可以顯著提高生產力。"},{"w":"product","p":"n.","d":"","c":"產品","s":"The company launched a new product that quickly became popular.","t":"該公司推出了一款很快就變得流行的新產品。"},{"w":"producer","p":"n.","d":"","c":"生產者","s":"The producer of the film received critical acclaim for their work.","t":"電影的製片人因其工作而獲得了影評人的好評。"},{"w":"manufacture","p":"v.","d":"","c":"製造","s":"The company manufactures electronic components for various industries.","t":"該公司為各種行業製造電子零件。"},{"w":"manufacturer","p":"n.","d":"","c":"製造商","s":"The manufacturer is known for its high-quality, durable products.","t":"這家製造商以其高品質、耐用的產品而聞名。"},{"w":"manufacturing","p":"n.","d":"","c":"製造業","s":"The city's economy is heavily reliant on manufacturing.","t":"這個城市的經濟在很大程度上依賴於製造業。"},{"w":"digital","p":"adj.","d":"","c":"數字的","s":"The digital age has transformed how we store and access information.","t":"數字時代改變了我們存儲和訪問信息的方式。"},{"w":"digit","p":"n.","d":"","c":"數字","s":"Please enter the last four digits of your social security number.","t":"請輸入您社會保險號的最後四位數字。"},{"w":"digital camera","p":"phr.","d":"","c":"數碼相機","s":"He captured stunning landscapes using his new digital camera.","t":"他用他的新數碼相機拍攝了令人驚嘆的風景。"},{"w":"display","p":"v.","d":"","c":"顯示","s":"The exhibit will display rare artifacts from ancient times.","t":"展覽將展示來自古代的稀有文物。"},{"w":"display","p":"n.","d":"","c":"顯示器","s":"The high-resolution display of the device provides clear and vibrant images.","t":"詣彩的高解析度顯示器提供清晰而鮮豔的圖像。"},{"w":"on display","p":"phr.","d":"","c":"展示","s":"The museum has a new collection on display until the end of the month.","t":"博物館有一個新的系列展品將展出至月底。"},{"w":"exhibit","p":"v.","d":"","c":"展出","s":"The artist will exhibit her latest paintings at the gallery.","t":"藝術家將在畫廊展出她的最新畫作。"},{"w":"exhibit","p":"n.","d":"","c":"單一展品","s":"The exhibit includes rare manuscripts from the medieval period.","t":"展品包括中世紀時期的稀有手稿。"},{"w":"exhibit / exhibition","p":"n.","d":"","c":"展覽","s":"The museum's new exhibit on ancient Egypt has attracted thousands of visitors.","t":"博物館關於古埃及的新展覽吸引了成千上萬的遊客。"},{"w":"development","p":"n.","d":"","c":"發展","s":"The development of new infrastructure has significantly improved the city's transport system.","t":"新基礎設施的發展顯著改善了城市的交通系統。"},{"w":"develop","p":"v.","d":"","c":"發展","s":"Researchers are working to develop a new vaccine for the disease.","t":"研究人員正在努力研發這種疾病的新疫苗。"},{"w":"develop the film","p":"phr.","d":"","c":"衝洗膠片","s":"In the darkroom, he learned how to develop the film manually.","t":"在暗房裡，他學會了如何手動衝洗膠片。"},{"w":"developer (of an app)","p":"phr.","d":"","c":"應用程式開發者","s":"The developer of the app introduced several new features in the latest update.","t":"應用程式開發者在最新更新中引入了幾項新功能。"},{"w":"developing country","p":"phr.","d":"","c":"發展中國家","s":"Many developing countries face challenges in achieving sustainable economic growth.","t":"許多發展中國家面臨實現可持續經濟增長的挑戰。"},{"w":"developed country","p":"phr.","d":"","c":"已開發國家","s":"Developed countries often have more resources to invest in healthcare and education.","t":"發達國家通常有更多資源投入到醫療保健和教育中。"},{"w":"screen","p":"n.","d":"","c":"屏幕","s":"The latest model of the phone has a larger and clearer screen.","t":"手機的最新型號擁有更大更清晰的屏幕。"},{"w":"screen","p":"v.","d":"","c":"篩選","s":"The committee will screen all candidates before making a final decision.","t":"委員會將在做出最終決定之前篩選所有候選人。"},{"w":"screening","p":"n.","d":"","c":"篩查","s":"The hospital offers free health screening for the community.","t":"醫院為社區提供免費健康篩查。"},{"w":"the big screen","p":"phr.","d":"","c":"大銀幕","s":"The movie is set to debut on the big screen next month.","t":"該電影計劃下個月在大銀幕上首映。"},{"w":"marriage","p":"n.","d":"","c":"婚姻","s":"Their marriage was a celebration of love and commitment.","t":"他們的婚姻是對愛和承諾的慶祝。"},{"w":"marriage / mixture","p":"n.","d":"","c":"結合","s":"The dish is a marriage of various flavors that blend harmoniously together.","t":"這道菜是各種口味的結合，融合得非常和諧。"},{"w":"marry","p":"v.","d":"","c":"結婚","s":"They plan to marry in a small wedding ceremony with close family and friends.","t":"他們計劃與親密的家人和朋友進行一個小型的儀式結婚。"},{"w":"married","p":"adj.","d":"","c":"已婚的","s":"The married couple moved into their new home last week after their wedding and honeymoon.","t":"這對已婚夫婦上週搬進了他們的新家，在他們婚禮和蜜月之後。"},{"w":"revolutionary","p":"adj.","d":"","c":"革命性的","s":"The scientist's revolutionary discovery changed the field of medicine.","t":"這位科學家的革命性發現改變了醫學領域。"},{"w":"revolution","p":"n.","d":"","c":"革命","s":"The industrial revolution had a profound impact on society and the economy.","t":"工業革命對社會和經濟產生了深遠的影響。"},{"w":"revolve","p":"v.","d":"","c":"旋轉","s":"The planets revolve around the sun in an elliptical orbit.","t":"行星沿著橢圓軌道繞太陽旋轉。"},{"w":"era / period of time","p":"n.","d":"","c":"時代","s":"The discovery marked the beginning of a new era in space exploration.","t":"這一發現標誌著太空探索新時代的開始。"},{"w":"technology","p":"n.","d":"","c":"技術","s":"Advances in technology have greatly improved communication worldwide.","t":"技術的進步大大改善了全球通信。"},{"w":"technological","p":"adj.","d":"","c":"技術的","s":"The technological advancements have made smart homes more accessible.","t":"技術進步使智能家居更加普及。"},{"w":"launch a product line / single/ album/ MV","p":"v.","d":"","c":"發行產品/單曲/專輯/影片","s":"The cosmetics company is set to launch its newest beauty and skin care product line next week.","t":"該美妝公司計劃於下週推出其最新美容與護膚產品系列。"},{"w":"launch a campaign/ movement/ program","p":"phr.","d":"","c":"發起活動","s":"The environmental organization will launch a campaign to raise public awareness of environmental conservation and sustainable development.","t":"該環保組織將發起一項活動，以提高人們對環境保護以及永續發展的意識。"},{"w":"launch a missile/ satellite","p":"phr.","d":"","c":"發射導彈","s":"The military conducted a test to launch a missile from the new defense system.","t":"軍方進行了一項測試，從新的防禦系統發射導彈。"},{"w":"launch","p":"n.","d":"","c":"啟動，發射","s":"The launch of the test satellite was watched by millions around the world in real time.","t":"數百萬人在全球範圍內同步觀看了衛星的發射。"}]},{"unit":10,"theme":"comfort – pretend","cards":[{"w":"comfort","p":"n.","d":"","c":"舒適","s":"The plush sofa provided great comfort after a long day at work.","t":"那把豪華的沙發為一天的工作後提供了極大的舒適。"},{"w":"comfort","p":"v.","d":"","c":"安慰","s":"She tried to comfort her friend who was feeling upset about the situation.","t":"她試圖安慰她感到不安的朋友，因為情況讓她感到沮喪。"},{"w":"discomfort","p":"n.","d":"","c":"不適","s":"The sudden change in temperature caused a feeling of discomfort among the hikers.","t":"溫度的突然變化使得徒步旅行者感到不適。"},{"w":"comfortable","p":"adj.","d":"","c":"舒適的","s":"The hotel room was spacious and comfortable, with all the amenities needed for a relaxing stay.","t":"酒店房間寬敞且舒適，配備了一切讓人放鬆的設施。"},{"w":"anxious","p":"adj.","d":"","c":"焦慮的","s":"He felt anxious before the important job interview, but he tried to stay calm and confident.","t":"在重要的求職面試之前，他感到焦慮，但他試圖保持冷靜和自信。"},{"w":"anxiety","p":"n.","d":"","c":"焦慮","s":"Anxiety can have physical and emotional effects on a person's well-being.","t":"焦慮可以對一個人的健康產生身體和情感方面的影響。"},{"w":"fit","p":"adj.","d":"","c":"合適的","s":"The dress was a perfect fit for the occasion, and she looked stunning in it.","t":"這件連衣裙非常合適這個場合，她穿上它看起來非常迷人。"},{"w":"fit","p":"v.","d":"","c":"適合","s":"Does this shirt fit you well? If not, we can find a different size.","t":"這件襯衫合身嗎？如果不合適，我們可以找到不同"},{"w":"fitness","p":"n.","d":"","c":"適合；健康","s":"Regular exercise is essential for maintaining good fitness and overall well-being.","t":"定期運動對於保持良好的健康狀態和整體幸福感至關重要。"},{"w":"fit","p":"n.","d":"","c":"適合；健康","s":"Finding the right fitness routine can be a challenge, but it's worth the effort for better health.","t":"找到合適的健身計劃可能具有挑戰性，但為了更好的健康，這是值得的。"},{"w":"fit in","p":"phr.","d":"","c":"融入；適應","s":"It can be difficult to fit in in a new social group, but making an effort to connect with others is important.","t":"在新的社交圈中融入可能會很困難，但努力與他人建立聯繫是很重要的。"},{"w":"claim","p":"v.","d":"","c":"聲稱；宣稱","s":"The company's marketing campaign claims that their product is the best on the market.","t":"公司的營銷活動聲稱他們的產品是市場上最好的。"},{"w":"claim","p":"v.","d":"","c":"要求；索賠","s":"After the accident, he had to claim compensation from the insurance company to cover his medical expenses.","t":"事故發生後，他不得不向保險公司要求賠償，以支付醫療費用。"},{"w":"success","p":"n.","d":"","c":"成功；勝利","s":"Success often requires hard work, determination, and the ability to learn from failures.","t":"成功通常需要努力、決心以及從失敗中吸取經驗的能力。"},{"w":"succeed","p":"v.","d":"","c":"成功；繼承","s":"With dedication and perseverance, she managed to succeed in her career and achieve her goals.","t":"她以奉獻精神和毅力，成功地在事業上取得了成就並實現了她的目標。"},{"w":"successful","p":"adj.","d":"","c":"成功的；卓越的","s":"The company's innovative strategies have led to a series of successful product launches and increased market share.","t":"公司的創新策略導致了一系列成功的產品推出和增加的市場份額。"},{"w":"weight","p":"n.","d":"","c":"體重","s":"Losing weight can have a positive impact on one's health, especially when combined with a balanced diet and exercise.","t":"減肥可以對健康產生積極的影響，尤其是當它與均衡的飲食和運動結合時。"},{"w":"weigh","p":"v.","d":"","c":"量重；稱重","s":"Please weigh yourself on the scale and let me know your current weight.","t":"請站在磅秤上量重，然後告訴我您目前的體重。"},{"w":"gain weight","p":"phr.","d":"","c":"增加體重；發胖","s":"Some people struggle to gain weight even with a healthy diet, and it may be due to various factors.","t":"一些人即使飲食健康也難以增加體重，這可能是由於各種因素造成的。"},{"w":"lose weight","p":"phr.","d":"","c":"減肥","s":"She decided to lose weight and adopted a fitness routine to achieve her weight loss goals.","t":"她決定減肥，採用健身計劃來實現她的減重目標。"},{"w":"tell the truth","p":"phr.","d":"","c":"說實話；講真話","s":"It's important to tell the truth in any situation, as honesty is the foundation of trust.","t":"在任何情況下說實話都很重要，因為誠實是信任的基礎。"},{"w":"true","p":"adj.","d":"","c":"真實的","s":"The detective finally uncovered the true identity of the mysterious masked man.","t":"這名偵探終於揭示了神秘的面具男子的真實身份。"},{"w":"truthful","p":"adj.","d":"","c":"誠實的","s":"She is known for being truthful and straightforward, never hiding the truth from her friends.","t":"她以誠實和坦率而著稱，從不對朋友隱瞞事實。"},{"w":"false","p":"adj.","d":"","c":"虛假的","s":"The newspaper published a false story, and it had to issue a public apology for the misinformation.","t":"這家報紙發布了一個虛假的故事，並不得不因錯誤信息發表公開道歉。"},{"w":"belief","p":"n.","d":"","c":"信仰；信念","s":"Cultural beliefs and values can vary greatly from one region to another, shaping people's worldviews.","t":"文化信仰和價值觀在不同地區可能有很大的不同，影響著人們的世界觀。"},{"w":"disbelief","p":"n.","d":"","c":"懷疑；不相信","s":"Many people expressed their disbelief when they first heard the unbelievable news.","t":"許多人在第一次聽到令人難以置信的消息時表現出了懷疑。"},{"w":"renewable energy","p":"n.","d":"","c":"可再生能源","s":"The transition to renewable energy sources such as wind and solar power is essential for reducing greenhouse gas emissions and combating climate change.","t":"轉向可再生能源，如風能和太陽能，對於減少溫室氣體排放和應對氣候變化至關重要。"},{"w":"speed","p":"v.","d":"","c":"加速；快速移動","s":"He decided to speed up the process by working extra hours to meet the project deadline.","t":"他決定通過加班工作來加速進程，以滿足項目的截止日期。"},{"w":"at ... speed","p":"phr.","d":"","c":"以...速度","s":"The car was traveling at an incredible speed, and the driver had to be cautious on the highway.","t":"車子以驚人的速度行駛，司機必須在高速公路上小心駕駛。"},{"w":"effect","p":"n.","d":"","c":"影響；效果","s":"The effects of climate change are becoming more apparent with rising temperatures and extreme weather events.","t":"氣候變化的影響隨著氣溫上升和極端天氣事件變得越來越明顯。"},{"w":"effective","p":"adj.","d":"","c":"有效的；生效的","s":"Regular exercise and a balanced diet are effective ways to improve one's overall health.","t":"定期運動和均衡飲食是改善整體健康的有效方法。"},{"w":"side effect","p":"n.","d":"","c":"副作用；不良反應","s":"Some medications may have side effects, so it's important to consult a doctor about potential risks.","t":"一些藥物可能會有副作用，因此重要的是咨詢醫生有關潛在風險。"},{"w":"come into effect","p":"phr.","d":"","c":"生效；實施","s":"The new law will come into effect next month, bringing significant changes to the legal system.","t":"新法將在下個月生效，對法律體系帶來重大變革。"},{"w":"affect","p":"v.","d":"","c":"影響；影響情感","s":"The loss of a loved one can affect a person's emotional well-being, leading to grief and sadness.","t":"失去親人可以影響一個人的情感幸福，引起悲傷和沮喪。"},{"w":"suggest","p":"v.","d":"","c":"暗示；提議","s":"His actions seemed to suggest that he was not happy with the decision, even though he didn't say anything explicitly.","t":"他的行為似乎在暗示他對決定不滿意，即使他沒有明確地說什麼。"},{"w":"suggest","p":"v.","d":"","c":"建議；提議","s":"I would like to suggest that we schedule a meeting to discuss the upcoming project in more detail.","t":"我建議我們安排一次會議，以更詳細地討論即將來臨的項目。"},{"w":"make a suggestion","p":"phr.","d":"","c":"提出建議","s":"If you have any ideas or concerns, please feel free to make a suggestion during the team meeting.","t":"如果你有任何想法或疑慮，請在團隊會議期間隨時提出建議。"},{"w":"unrealistic","p":"adj.","d":"","c":"不切實際的","s":"Setting unrealistic expectations can lead to disappointment when goals are not achieved.","t":"設定不切實際的期望可能會在未達到目標時導致失望。"},{"w":"realistic","p":"adj.","d":"","c":"現實的；切實的","s":"It's important to set realistic goals that are achievable within a given timeframe.","t":"設定現實的目標很重要，這些目標在給定的時間內是可以實現的。"},{"w":"realize","p":"v.","d":"","c":"實現；實現夢想","s":"After years of hard work, she finally realized her dream of opening her own business.","t":"經過多年的努力，她終於實現了開設自己生意的夢想。"},{"w":"realize","p":"v.","d":"","c":"理解；意識到","s":"It took some time for him to realize the importance of work-life balance and its impact on his well-being.","t":"他花了一些時間才意識到工作和生活平衡的重要性以及它對他的幸福感的影響。"},{"w":"accurate","p":"adj.","d":"","c":"準確的；精確的","s":"The scientific experiment yielded accurate results, confirming the hypothesis.","t":"這個科學實驗產生了準確的結果，證實了假設。"},{"w":"inaccurate","p":"adj.","d":"","c":"不準確的；錯誤的","s":"The news report contained several inaccurate statements that needed correction.","t":"這則新聞報導包含了一些需要更正的不準確語句。"},{"w":"accuracy","p":"n.","d":"","c":"準確性；精確性","s":"The accuracy of the weather forecast can greatly impact people's plans and preparations.","t":"天氣預報的準確性可以極大地影響人們的計劃和準備。"},{"w":"sense","p":"v.","d":"","c":"感覺到 / 察覺","s":"Even before the storm began, the animals seemed to sense the change in air pressure and started seeking shelter.","t":"甚至在風暴開始之前，動物們似乎就察覺到了氣壓的變化，並開始尋找庇護所。"},{"w":"sense","p":"n.","d":"","c":"感覺；感知","s":"Our sense of taste allows us to distinguish between various flavors in food and beverages.","t":"我們的味覺允許我們區分食物和飲料中的各種風味。"},{"w":"sensitive","p":"adj.","d":"","c":"敏感的；感光的","s":"Some individuals have sensitive skin that reacts quickly to environmental changes and skincare products.","t":"一些人擁有敏感的皮膚，對環境變化和護膚產品作出迅速反應。"},{"w":"be sensitive to","p":"phr.","d":"","c":"對...敏感 / 體貼","s":"A good teacher should be sensitive to the needs of their students, noticing when someone is struggling even if they don't ask for help.","t":"一位好老師應該對學生的需求保持敏感，即使學生沒有主動求助，也能察覺到誰正在面臨困難。"},{"w":"sensible","p":"adj.","d":"","c":"明智的 / 合理的","s":"It would be sensible to save a portion of your salary every month rather than spending it all on luxury items you don't need.","t":"每個月存下一部分薪水，而不是把錢都花在不需要的奢侈品上，這才是明智之舉。"},{"w":"make sense","p":"phr.","d":"","c":"有道理 / 講得通","s":"The detective realized that the suspect's alibi didn't make sense because the timings provided contradicted the security footage.","t":"偵探意識到嫌疑犯的不在場證明講不通，因為提供的時間點與監視錄影畫面相矛盾。"},{"w":"a sense of","p":"phr.","d":"","c":"...感","s":"Joining a local club can give you a sense of belonging and help you make friends with similar interests.","t":"加入當地的社團可以給你一種歸屬感，並幫助你結交志趣相投的朋友。"},{"w":"a sense of responsibility","p":"phr.","d":"","c":"責任感","s":"Taking care of a pet at a young age helps children develop a strong sense of responsibility and teaches them how to care for others.","t":"從小照顧寵物有助於培養孩子強烈的責任感，並教會他們如何照顧他人。"},{"w":"a sense of humor","p":"phr.","d":"","c":"幽默感","s":"Having a good sense of humor can help people cope with stressful situations by finding something lighthearted in difficult moments.","t":"擁有良好的幽默感可以幫助人們在困難時刻找到輕鬆的一面，從而應對壓力。"},{"w":"a sense of achievement","p":"phr.","d":"","c":"成就感","s":"Completing a marathon after months of rigorous training gives runners an incredible sense of achievement.","t":"在經過數月嚴格訓練後完成馬拉松比賽，會給跑者帶來巨大的成就感。"},{"w":"a sense of direction","p":"phr.","d":"","c":"方向感","s":"Without a GPS, I would certainly get lost in the city because I have a terrible sense of direction and can't read maps well.","t":"如果沒有全球定位系統，我肯定會在城市裡迷路，因為我的方向感很差，也不太會看地圖。"},{"w":"sensible","p":"adj.","d":"","c":"明智的；理智的","s":"It's sensible to save money for unexpected expenses rather than spending it all on non-essential items.","t":"為意外開支而儲蓄錢財而不是花費在非必要物品上是明智的。"},{"w":"wise","p":"adj.","d":"","c":"智慧的；聰明的","s":"The elderly man shared his wise advice on how to lead a fulfilling and meaningful life.","t":"老人分享了他的智慧建議，教人如何過上充實有意義的生活。"},{"w":"wisdom","p":"n.","d":"","c":"智慧","s":"Over the years, the grandmother shared her wisdom with the younger generation, teaching them the importance of patience and kindness.","t":"多年來，祖母與年輕一代分享她的智慧，教導他們耐心與善良的重要性。"},{"w":"fiction","p":"n.","d":"","c":"虛構小說；小說","s":"Science fiction allows us to explore imaginative worlds and contemplate the possibilities of the future.","t":"科幻小說讓我們能夠探索富有想象力的世界，思考未來的可能性。"},{"w":"fictional","p":"adj.","d":"","c":"虛構的；小說中的","s":"The movie is based on a fictional story about a legendary hero who embarks on a quest to save the kingdom.","t":"這部電影基於一個虛構故事，講述了一位傳奇英雄展開冒險拯救王國的故事。"},{"w":"disguise","p":"v.","d":"","c":"偽裝；掩飾","s":"He tried to disguise his true identity by wearing a mask and speaking in a different accent.","t":"他試圖通過戴面具並以不同的口音說話來掩飾自己的真實身份。"},{"w":"disguise","p":"n.","d":"","c":"偽裝；掩飾","s":"The spy wore a clever disguise to blend in with the crowd and avoid detection during the mission.","t":"間諜穿著巧妙的偽裝，以融入人群並在任務期間避免被發現。"},{"w":"A blessing in disguise","p":"phr.","d":"","c":"塞翁失馬焉知非福","s":"Losing his job turned out to be a blessing in disguise, as it gave him the opportunity to pursue his true passion.","t":"失去工作最終變成了一種福祉，因為它給了他追求自己真正熱愛的機會。"},{"w":"pretend","p":"v.","d":"","c":"假裝","s":"Even though he was feeling quite nervous about the presentation, he tried to pretend to be confident in front of the audience.","t":"儘管他對這場簡報感到相當緊張，他仍試圖在觀眾面前假裝得很自信。"}]},{"unit":11,"theme":"wonder – dare to V","cards":[{"w":"wonder","p":"n.","d":"","c":"奇蹟","s":"The Great Wall of China is a wonder of engineering.","t":"中國的長城是工程學上的一個奇蹟。"},{"w":"wonder","p":"v.","d":"","c":"感到驚奇","s":"I often wonder about the mysteries of the universe.","t":"我常常對宇宙的神秘事物感到驚奇。"},{"w":"wonder","p":"v.","d":"","c":"想知道","s":"I wonder why the eggs are in short supply.","t":"我想知道為什麼雞蛋供應量不足短缺。"},{"w":"tropical","p":"adj.","d":"","c":"熱帶的","s":"The tropical climate is characterized by high humidity.","t":"熱帶氣候的特點是高濕度。"},{"w":"subtropical","p":"adj.","d":"","c":"亞熱帶的","s":"This region has a subtropical environment, suitable for diverse flora.","t":"這個區域有著亞熱帶的環境，適合各種植物生長。"},{"w":"temperate","p":"adj.","d":"","c":"溫帶的","s":"The temperate zone experiences four distinct seasons.","t":"溫帶地區經歷四個不同的季節。"},{"w":"tend to","p":"phr.","d":"","c":"傾向於","s":"People tend to prefer stability over uncertainty.","t":"人們傾向於偏好穩定超過不確定性。"},{"w":"tendency","p":"n.","d":"","c":"傾向","s":"There is a tendency for younger generations to embrace technology.","t":"年輕一代有傾向於接受技術。"},{"w":"intend to V","p":"phr.","d":"","c":"打算","s":"I intend to travel to Europe next summer.","t":"我打算明年夏天去歐洲旅行。"},{"w":"intension","p":"n.","d":"","c":"意圖","s":"His intension behind the decision was unclear.","t":"他做出這個決定的意圖不明朗。"},{"w":"theory","p":"n.","d":"","c":"理論","s":"Einstein's theory of relativity revolutionized physics.","t":"愛因斯坦的相對論理論顛覆了物理學。"},{"w":"theorize","p":"v.","d":"","c":"理論化","s":"Scientists often theorize to explain natural phenomena.","t":"科學家們經常理論化來解釋自然現象。"},{"w":"theoretical","p":"adj.","d":"","c":"理論上的","s":"The theoretical aspects of this study are challenging.","t":"這項研究的理論方面是有挑戰性的。"},{"w":"sweat","p":"n.","d":"","c":"汗","s":"After a long run, he was covered in sweat.","t":"長時間跑步後，他滿身是汗。"},{"w":"focus on / concentrate on","p":"phr.","d":"","c":"專注於","s":"It's important to focus on the task at hand.","t":"關注手頭的任務是很重要的。"},{"w":"vary","p":"v.","d":"","c":"(使)不同 / 改變","s":"The cost of living can vary significantly from one city to another, depending on local taxes and housing demands.","t":"生活成本在不同城市之間可能會有顯著差異，這取決於當地的稅收和住房需求。"},{"w":"a variety of","p":"phr.","d":"","c":"各種各樣的","s":"The festival featured a variety of cultural performances.","t":"節日展示了各種各樣的文化表演。"},{"w":"various","p":"adj.","d":"","c":"各種不同的","s":"There were various opinions on the matter.","t":"對這件事有各種意見"},{"w":"varied","p":"adj.","d":"","c":"多變的","s":"The exhibition displayed a varied collection of artworks.","t":"展覽展示了多變的藝術作品收藏。"},{"w":"available","p":"adj.","d":"","c":"可用的","s":"The information is readily available online.","t":"資訊在線上容易取得。"},{"w":"grain","p":"n.","d":"","c":"穀物","s":"Rice is a staple grain in many countries.","t":"在許多國家，米是主要的穀物。"},{"w":"source","p":"n.","d":"","c":"來源","s":"The river is the main source of water for the region.","t":"這條河是該地區主要的水源。"},{"w":"source out","p":"phr.","d":"","c":"尋找來源","s":"We need to source out quality materials for our new product.","t":"我們需要為我們的新產品尋找優質材料。"},{"w":"origin","p":"n.","d":"","c":"起源","s":"The origin of the festival dates back to ancient times.","t":"節日的起源可以追溯到古代。"},{"w":"original","p":"adj.","d":"","c":"原本的","s":"The painting was restored to its original state.","t":"這幅畫被恢復到其原本的狀態。"},{"w":"original","p":"adj.","d":"","c":"原創的","s":"She is known for her original ideas in design.","t":"她以她在設計上的原創想法而聞名。"},{"w":"originate from","p":"phr.","d":"","c":"起源於","s":"The cuisine originates from the Mediterranean region.","t":"這種美食起源於地中海地區。"},{"w":"range from A to B","p":"phr.","d":"","c":"範圍從A到B","s":"Prices range from $50 to $200.","t":"價格範圍從50美元到200美元。"},{"w":"ranging from","p":"phr.","d":"","c":"範圍從…到…","s":"The store offers products ranging from clothing to electronics.","t":"這家商店提供的產品範圍從服裝到電子產品。"},{"w":"range","p":"n.","d":"","c":"範圍","s":"The hotel offers a wide range of services.","t":"這家酒店提供廣泛的服務範圍。"},{"w":"mixed","p":"adj.","d":"","c":"混合的","s":"The team is mixed in terms of skills and experience.","t":"這支隊伍在技能和經驗方面是混合的。"},{"w":"mixture","p":"n.","d":"","c":"混合物","s":"The recipe calls for a mixture of spices.","t":"食譜要求使用一種香料混合物。"},{"w":"beside","p":"n.","d":"","c":"在...旁邊","s":"She sat beside her friend during the concert.","t":"她在音樂會期間坐在她朋友旁邊。"},{"w":"deny","p":"v.","d":"","c":"否認","s":"He tried to deny any involvement in the scandal.","t":"他試圖否認在醜聞中的任何牽連。"},{"w":"denial","p":"n.","d":"","c":"否認","s":"His denial of the charges was expected.","t":"他對指控的否認是預料之中的。"},{"w":"there is no denying that","p":"phr.","d":"","c":"不可否認","s":"There is no denying that technology has changed our lives.","t":"不可否認科技改變了我們的生活。"},{"w":"admit","p":"v.","d":"","c":"承認","s":"After hours of questioning, the suspect finally decided to admit that he had been at the scene of the crime.","t":"經過數小時的審問，嫌疑人最終決定承認他曾出現在犯罪現場。"},{"w":"admit","p":"v.","d":"","c":"錄取","s":"The prestigious university will only admit a small percentage of applicants each year to maintain its high academic standards.","t":"這所名牌大學每年僅錄取極少數比例的申請者，以維持其高水準的學術要求。"},{"w":"be admitted to","p":"phr.","d":"","c":"被錄取 / 獲准進入","s":"She was overjoyed to find out that she had been admitted to her first-choice medical school after a rigorous interview process.","t":"在經過嚴格的面試過程後，她欣喜若狂地發現自己被第一志願的醫學院錄取了。"},{"w":"admissions","p":"n.","d":"","c":"入學許可 / 入學人數","s":"The university's admissions office is responsible for reviewing thousands of personal statements and recommendation letters annually.","t":"該大學的招生辦公室負責每年審查數千份的個人陳述與推薦信。"},{"w":"admission","p":"n.","d":"","c":"承認 / 入場費","s":"His sudden admission of guilt surprised everyone in the courtroom, as he had previously claimed total innocence.","t":"他突然承認有罪讓法庭上的每個人都感到驚訝，因為他之前聲稱完全清白。"},{"w":"dare to V","p":"phr.","d":"","c":"敢於做某事","s":"Few people dare to challenge the established norms.","t":"很少有人敢於挑戰既定的規範。"}]},{"unit":12,"theme":"landmark – be diagnosed with","cards":[{"w":"landmark","p":"n.","d":"","c":"地標","s":"As we strolled through the historic city, the towering landmark reminded us of its rich cultural heritage.","t":"當我們漫步在這個歷史悠久的城市時，高聳的地標讓我們想起了它豐富的文化遺產。"},{"w":"average","p":"n.","d":"","c":"平均","s":"According to the latest report, the average income of households in the region has increased significantly over the past decade.","t":"根據最新報告，該地區家庭的平均收入在過去十年中顯著增加。"},{"w":"average","p":"adj.","d":"","c":"平均的","s":"Despite his average performance in the preliminary rounds, he managed to secure a spot in the finals.","t":"儘管他在初賽中的表現平平，但他還是成功地獲得了決賽的名額。"},{"w":"maximum","p":"n.","d":"","c":"最大限度","s":"The concert hall has a strict policy of adhering to the maximum capacity of 1000 attendees to ensure safety.","t":"音樂廳嚴格遵守最大容量1000名參與者的政策，以確保安全。"},{"w":"maximum","p":"adj.","d":"","c":"最大的","s":"To achieve the maximum benefit from this exercise, it's important to maintain the correct posture throughout.","t":"為了從這項運動中獲得最大的益處，保持正確的姿勢是非常重要的。"},{"w":"minimum","p":"adj.","d":"","c":"最小限度/最小的","s":"The job requires a minimum level of experience, preferably at least two years in a related field.","t":"這份工作要求最低程度的經驗，最好是在相關領域至少有兩年的經驗。"},{"w":"per","p":"n.","d":"","c":"每","s":"The cost of the project is calculated at 50 dollars per hour of labor, which includes all the necessary materials and tools.","t":"該項目的成本按每小時50美元的人工計算，包括所有必需的材料和工具。"},{"w":"frequency","p":"n.","d":"","c":"頻率","s":"The frequency of trains during rush hour is increased to accommodate the large number of commuters.","t":"為了滿足大量通勤者的需求，在尖峰時段增加了列車的運行頻率。"},{"w":"frequent","p":"adj.","d":"","c":"頻繁的","s":"He is known for his frequent business trips to Europe, often traveling there several times a month.","t":"他以經常去歐洲出差而聞名，通常一個月要去那裡好幾次。"},{"w":"assume","p":"v.","d":"","c":"假設","s":"While analyzing the data, we must not assume that all variables are independent, as this could skew the results.","t":"在分析數據時，我們不能假設所有變量都是獨立的，因為這可能會扭曲結果。"},{"w":"assumed","p":"adj.","d":"","c":"假定的","s":"His assumed innocence was questioned after new evidence was presented in court.","t":"在法庭上出示新證據後，他被假定的無辜受到質疑。"},{"w":"assumption","p":"n.","d":"","c":"假設","s":"The assumption that the economy will recover quickly may not hold true given the current global challenges.","t":"鑑於當前的全球挑戰，經濟將迅速復甦的假設可能不成立。"},{"w":"infect","p":"v.","d":"","c":"感染","s":"During the outbreak, many people were afraid to go outside, worrying they might infect others unknowingly.","t":"在疫情爆發期間，許多人害怕外出，擔心他們可能無意中感染他人。"},{"w":"be infected with","p":"phr.","d":"","c":"被…感染","s":"After visiting the affected region, several aid workers were found to be infected with a rare virus.","t":"在訪問受影響的地區後，發現幾名救援工作者感染了一種罕見的病毒。"},{"w":"moist","p":"adj.","d":"","c":"潮濕的","s":"The moist climate of the tropical island is ideal for growing certain fruits.","t":"這個熱帶島嶼的潮濕氣候非常適合種植某些水果。"},{"w":"moisture","p":"n.","d":"","c":"濕氣","s":"Plants in this region rely on the early morning moisture for their water needs.","t":"這個地區的植物依靠清晨的濕氣來滿足它們的水分需求。"},{"w":"moisturize","p":"v.","d":"","c":"保濕","s":"In dry climates, it's important to moisturize your skin regularly to prevent it from cracking.","t":"在乾燥的氣候中，定期保濕你的皮膚以防止它開裂是很重要的。"},{"w":"humid","p":"adj.","d":"","c":"潮濕的","s":"The humid weather during the monsoon season makes outdoor activities less appealing.","t":"季風季節的潮濕天氣使戶外活動變得不那麼吸引人。"},{"w":"continue","p":"v.","d":"","c":"繼續","s":"Despite the challenges, the team decided to continue with the project, showing great determination.","t":"儘管面臨挑戰，團隊決定繼續進行這個項目，展現了極大的決心。"},{"w":"continuous","p":"adj.","d":"","c":"連續的","s":"The continuous rainfall for several days led to flooding in many areas.","t":"連續幾天的降雨導致許多地區發生洪水。"},{"w":"continuity","p":"n.","d":"","c":"連續性","s":"The director was praised for maintaining the continuity of the storyline throughout the film.","t":"導演因在整部電影中維持故事情節的連續性而受到讚揚。"},{"w":"rage","p":"n.","d":"","c":"憤怒","s":"The debate sparked a rage among the community members, leading to heated discussions.","t":"辯論在社區成員中引發了憤怒，導致熱烈的討論。"},{"w":"rage","p":"v.","d":"","c":"發怒","s":"He began to rage when he heard about the unfair treatment.","t":"當他聽說不公平的待遇時，他開始發怒。"},{"w":"rage","p":"v.","d":"","c":"激烈進行","s":"The storm continued to rage throughout the night, causing widespread damage.","t":"風暴持續在整個夜晚激烈進行，造成了廣泛的損害。"},{"w":"rage on","p":"phr.","d":"","c":"繼續激烈進行","s":"Despite efforts to control it, the wildfire raged on for weeks.","t":"儘管努力控制，野火持續燃燒了數週。"},{"w":"outrage","p":"n.","d":"","c":"憤怒","s":"The scandal caused public outrage and demands for justice.","t":"這起醜聞引起了公眾的憤怒和對正義的要求。"},{"w":"all the rage","p":"phr.","d":"","c":"非常流行","s":"Slim-fit jeans are all the rage among teenagers this year.","t":"今年，緊身牛仔褲在青少年中非常流行。"},{"w":"grief","p":"n.","d":"","c":"悲傷","s":"After the loss of her pet, she was overwhelmed with grief.","t":"在失去她的寵物後，她感到非常悲傷。"},{"w":"to one's grief","p":"phr.","d":"","c":"令某人悲傷","s":"To his grief, he discovered that the old tree in his backyard had been cut down.","t":"令他悲傷的是，他發現後院的老樹被砍掉了。"},{"w":"grieve","p":"v.","d":"","c":"哀悼","s":"She continues to grieve the loss of her close friend.","t":"她繼續哀悼她親密朋友的去世。"},{"w":"decrease","p":"v.","d":"","c":"減少","s":"The government's new policies aim to decrease air pollution in urban areas.","t":"政府的新政策旨在減少城市地區的空氣污染。"},{"w":"the decrease in","p":"n.","d":"","c":"減少","s":"The report highlighted the decrease in consumer spending during the economic downturn.","t":"報告強調了經濟衰退期間消費支出的減少。"},{"w":"increase","p":"v.","d":"","c":"增加","s":"Efforts to increase public awareness about environmental protection have been successful.","t":"增加公眾對環境保護意識的努力已經取得成功。"},{"w":"increase in","p":"n.","d":"","c":"增加","s":"The recent increase in traffic congestion is mainly due to road construction.","t":"最近交通擁堵的增加主要是由於道路建設。"},{"w":"harm","p":"n.","d":"","c":"傷害","s":"The chemical spill caused significant harm to the marine ecosystem.","t":"化學洩漏對海洋生態系統造成了重大傷害。"},{"w":"harm","p":"v.","d":"","c":"傷害","s":"Smoking can seriously harm your health.","t":"吸煙可以嚴重傷害你的健康。"},{"w":"do harm to","p":"phr.","d":"","c":"對...造成傷害","s":"Polluting factories do harm to the environment and human health.","t":"污染工廠對環境和人類健康造成傷害。"},{"w":"harmful","p":"adj.","d":"","c":"有害的","s":"Consuming too much sugar is harmful to one's health.","t":"過量消耗糖分對一個人的健康有害。"},{"w":"harmless","p":"adj.","d":"","c":"無害的","s":"Most spiders are harmless to humans, despite common fears.","t":"大多數蜘蛛對人類是無害的，儘管人們常常感到害怕。"},{"w":"float","p":"v.","d":"","c":"漂浮","s":"Leaves float gently on the surface of the water.","t":"樹葉在水面上輕輕漂浮。"},{"w":"feel like + ving","p":"phr.","d":"","c":"想要做某事","s":"After a long week at work, I really feel like taking a long walk in the park.","t":"經過一周繁忙的工作後，我真的想在公園裡散散步。"},{"w":"feel like","p":"phr.","d":"","c":"像是","s":"Sometimes, being a parent feels like a never-ending challenge.","t":"有時候，做父母親就像是一個永無止境的挑戰。"},{"w":"weep","p":"v.","d":"","c":"哭泣","s":"She wept tears of joy when she heard the good news.","t":"當她聽到好消息時，她哭泣出了喜悅的眼淚。"},{"w":"sob","p":"v.","d":"","c":"啜泣","s":"Overwhelmed by emotion, he began to sob quietly in the corner.","t":"在情緒的壓倒下，他開始在角落裡悄悄啜泣。"},{"w":"infection","p":"n.","d":"","c":"感染","s":"The patient was treated immediately for a severe infection.","t":"醫生立刻治療了病人嚴重的感染。"},{"w":"infectious","p":"adj.","d":"","c":"傳染的","s":"Chickenpox is highly infectious and can spread quickly in crowded places.","t":"水痘是高度傳染的，並且可以在擁擠的地方迅速傳播。"},{"w":"diagnose","p":"v.","d":"","c":"診斷","s":"The doctor diagnosed her condition as an allergic reaction.","t":"醫生診斷她的狀況是過敏反應。"},{"w":"be diagnosed as","p":"phr.","d":"","c":"被診斷為...","s":"He was diagnosed as early-stage diabetes, prompting lifestyle changes.","t":"他被診斷為早期糖尿病，促使他改變生活方式。"},{"w":"be diagnosed with","p":"phr.","d":"","c":"被診斷出患有...","s":"Several patients in the hospital were diagnosed with pneumonia.","t":"醫院裡的幾位病人被診斷出患有肺炎。"}]},{"unit":13,"theme":"character – prime","cards":[{"w":"character","p":"n.","d":"","c":"角色","s":"In the novel, the main character faces many challenges.","t":"在小說中，主角面臨許多挑戰。"},{"w":"character","p":"n.","d":"","c":"漢文文字","s":"Each Chinese character has its unique meaning and pronunciation.","t":"每個漢字都有其獨特的意義和發音。"},{"w":"character","p":"n.","d":"","c":"事務特性特質","s":"Honesty is an important character in a good leader.","t":"誠實是優秀領導者的一個重要特質。"},{"w":"characteristic","p":"n.","d":"","c":"特色","s":"The characteristic of this wine is its rich aroma.","t":"這種葡萄酒的特色是其濃郁的香氣。"},{"w":"characteristic","p":"adj.","d":"","c":"特有的，表示出特性的","s":"This bird is known for its characteristic bright plumage.","t":"這種鳥以其特有的鮮豔羽毛聞名。"},{"w":"be characteristic of","p":"phr.","d":"","c":"是…的特徵","s":"The use of vivid colors is characteristic of her painting style.","t":"使用鮮豔的顏色是她的繪畫風格的特徵。"},{"w":"spark","p":"v.","d":"","c":"引發","s":"The politician's speech sparked a lot of public debate.","t":"政治家的演講引發了許多公共辯論。"},{"w":"spark","p":"v.","d":"","c":"點燃火花","s":"Rubbing the two stones together sparks a fire.","t":"兩塊石頭摩擦在一起點燃了火。"},{"w":"spark","p":"n.","d":"","c":"點燃","s":"The spark from the firework was beautiful.","t":"煙火的火花很美。"},{"w":"spark","p":"n.","d":"","c":"閃光","s":"The diamond ring had a bright spark in the sunlight.","t":"鑽石戒指在陽光下有亮麗的閃光。"},{"w":"sparkle","p":"v.","d":"","c":"閃耀","s":"The stars sparkle in the night sky.","t":"星星在夜空中閃耀。"},{"w":"sparkling","p":"adj.","d":"","c":"閃閃發光的","s":"Her sparkling eyes revealed her excitement.","t":"她閃閃發光的眼睛透露出她的興奮。"},{"w":"intense","p":"adj.","d":"","c":"強烈的","s":"The intense heat of the summer sun can be overwhelming.","t":"夏日烈日的強烈熱度可能令人難以承受。"},{"w":"intensify","p":"v.","d":"","c":"加劇","s":"The debate intensified as opinions clashed.","t":"隨著意見的衝突，辯論加劇了。"},{"w":"intensity","p":"n.","d":"","c":"強度","s":"The intensity of the workout left everyone exhausted.","t":"運動的強度讓每個人都筋疲力盡。"},{"w":"intensive","p":"adj.","d":"","c":"密集的","s":"The course offers intensive language training.","t":"課程提供密集的語言訓練。"},{"w":"intensive reading","p":"phr.","d":"","c":"精讀","s":"Intensive reading helps students to understand the text deeply.","t":"精讀幫助學生深入理解文本。"},{"w":"tense","p":"adj.","d":"","c":"緊張的","s":"The atmosphere in the room was tense during the meeting.","t":"會議期間，房間內的氣氛很緊張。"},{"w":"tension","p":"n.","d":"","c":"緊張","s":"The tension between the two countries is rising.","t":"兩國之間的緊張局勢正在上升。"},{"w":"argue","p":"v.","d":"","c":"爭吵","s":"They often argue about trivial matters.","t":"他們經常為了瑣事爭吵。"},{"w":"argue","p":"v.","d":"","c":"主張","s":"He argues that more research is needed on this topic.","t":"他主張這個話題需要更多研究。"},{"w":"argument","p":"n.","d":"","c":"爭吵","s":"Their argument ended in a mutual apology.","t":"他們的爭吵以彼此道歉而結束。"},{"w":"argument","p":"n.","d":"","c":"論點","s":"Her argument was supported by strong evidence and proof.","t":"她的論點得到了強有力的證據支持。"},{"w":"illustrate","p":"v.","d":"","c":"畫插圖","s":"The book is beautifully illustrated by a famous artist.","t":"這本書由一位著名藝術家精美插圖。"},{"w":"illustration","p":"n.","d":"","c":"插畫","s":"The illustration in the book brought the story to life.","t":"書中的插畫使故事栩栩如生。"},{"w":"illustrate","p":"v.","d":"","c":"圖示，解說","s":"The professor used a diagram to illustrate his point.","t":"教授用一個圖表來說明他的觀點。"},{"w":"illustration","p":"n.","d":"","c":"解說","s":"The illustration on the board helped students understand the concept.","t":"黑板上的解說幫助學生理解概念。"},{"w":"before long","p":"phr.","d":"","c":"不久","s":"Before long, she became proficient in three languages.","t":"不久，她精通了三種語言。"},{"w":"in no time","p":"phr.","d":"","c":"很快","s":"He finished the task in no time.","t":"他很快就完成了任務。"},{"w":"revise","p":"v.","d":"","c":"修訂","s":"She had to revise her essay before submission.","t":"她必須在提交前修訂她的文章。"},{"w":"revised","p":"adj.","d":"","c":"經修訂的","s":"The revised edition of the book included additional chapters.","t":"這本書的修訂版加入了額外的章節。"},{"w":"revision","p":"n.","d":"","c":"修訂","s":"The document went through several revisions before final approval.","t":"這份文件在最終批准前經歷了好幾次修訂。"},{"w":"modify","p":"v.","d":"","c":"修改","s":"The plan had to be modified to meet new requirements.","t":"計劃必須修改以滿足新的要求。"},{"w":"genetically-modified food","p":"phr.","d":"","c":"基因改造食品","s":"Many people have concerns about the safety of genetically-modified food.","t":"許多人對基因改造食品的安全性有所擔憂。"},{"w":"modification","p":"n.","d":"","c":"修改","s":"The car underwent several modifications to improve its performance.","t":"為了提高性能，這輛車進行了幾次修改。"},{"w":"lock","p":"v.","d":"","c":"鎖","s":"Remember to lock the door when you leave.","t":"離開時記得鎖門。"},{"w":"lock","p":"n.","d":"","c":"鎖","s":"She lost the key to the lock.","t":"她丟了鎖的鑰匙。"},{"w":"unlock","p":"v.","d":"","c":"解鎖","s":"He used the code to unlock the safe.","t":"他用密碼來解開保險箱。"},{"w":"locker","p":"n.","d":"","c":"儲物櫃","s":"He stored his belongings in the locker at the gym.","t":"他在健身房的儲物櫃裡存放了他的個人物品。"},{"w":"voice","p":"v.","d":"","c":"表明意見","s":"She voiced her concerns at the meeting.","t":"她在會議上表達了她的擔憂。"},{"w":"voice","p":"v.","d":"","c":"配音旁白","s":"He voices a character in the animated film.","t":"他為動畫電影中的一個角色配音。"},{"w":"voice","p":"n.","d":"","c":"聲音","s":"Her voice was soft and soothing.","t":"她的聲音柔和且舒緩。"},{"w":"voicemail","p":"n.","d":"","c":"語音郵件","s":"He left a message on her voicemail.","t":"他在她的語音郵件上留了消息。"},{"w":"give voice to","p":"phr.","d":"","c":"表達","s":"The article gives voice to the concerns of the community.","t":"這篇文章表達了社區的擔憂。"},{"w":"opinion","p":"n.","d":"","c":"意見","s":"In my opinion, the plan is not feasible.","t":"我認為這個計劃是不可行的。"},{"w":"in my opinion","p":"phr.","d":"","c":"我認為","s":"In my opinion, we should approach the problem differently.","t":"我認為，我們應該用不同的方式來處理這個問題。"},{"w":"voice one's opinion","p":"phr.","d":"","c":"發表意見","s":"It is important to voice your opinion in a democratic society.","t":"在民主社會中發表意見是很重要的。"},{"w":"proof","p":"n.","d":"","c":"證據","s":"The proof of his innocence was undeniable.","t":"他清白的證據是不可否認的。"},{"w":"the proof is in the pudding","p":"phr.","d":"","c":"結果證明一切","s":"We'll see if the plan works; the proof is in the pudding.","t":"我們將看到計劃是否有效；結果證明一切。"},{"w":"water-proof","p":"adj.","d":"","c":"防水的","s":"She bought a water-proof watch for her diving trip.","t":"她為她的潛水之旅買了一塊防水手錶。"},{"w":"wind-proof","p":"adj.","d":"","c":"防風的","s":"The wind-proof jacket was perfect for the hike.","t":"這件防風夾克非常適合遠足。"},{"w":"bullet-proof","p":"adj.","d":"","c":"防彈的","s":"The police wore bullet-proof vests during the operation.","t":"警察在行動中穿著防彈背心。"},{"w":"prove","p":"v.","d":"","c":"證明","s":"The experiment proved his theory to be correct.","t":"實驗證明他的理論是正確的。"},{"w":"proved","p":"adj.","d":"","c":"被證明的","s":"The proved benefits of exercise are numerous.","t":"運動被證明的好處是眾多的。"},{"w":"comment","p":"v.","d":"","c":"評論","s":"The teacher commented on the student's progress.","t":"老師評論了學生的進步。"},{"w":"comment","p":"n.","d":"","c":"評論","s":"His comment on the issue was insightful.","t":"他對這個問題的評論很有洞察力。"},{"w":"make a comment on","p":"phr.","d":"","c":"對…作評論","s":"Many people made a comment on the new policy.","t":"許多人對新政策作出了評論。"},{"w":"have no comment on/about","p":"phr.","d":"","c":"對…無可評論","s":"The official said he had no comment on the ongoing investigation.","t":"官員說他對正在進行的調查無可評論。"},{"w":"imply","p":"v.","d":"","c":"暗示","s":"His silence seemed to imply disapproval.","t":"他的沉默似乎暗示著不贊同。"},{"w":"implied","p":"adj.","d":"","c":"被暗示的","s":"The implied meaning of his words was clear.","t":"他話語中被暗示的意思是清楚的。"},{"w":"implication","p":"n.","d":"","c":"暗示","s":"The implications of his statement were far-reaching.","t":"他的聲明所暗示的後果是深遠的。"},{"w":"interpret","p":"v.","d":"","c":"解釋","s":"She interprets the poem in a unique way.","t":"她以一種獨特的方式解釋了這首詩。"},{"w":"interpret A as B","p":"phr.","d":"","c":"把A解釋為B","s":"He interpreted her silence as agreement.","t":"他把她的沉默解釋為同意。"},{"w":"interpretation","p":"n.","d":"","c":"解釋","s":"Different experts had different interpretations of the data.","t":"不同的專家對數據有不同的解釋。"},{"w":"secondary","p":"adj.","d":"","c":"次要的","s":"The secondary effects of the medication were minimal.","t":"藥物的次要作用是微乎其微的。"},{"w":"primary","p":"adj.","d":"","c":"主要的","s":"The primary goal of the project was to improve safety.","t":"該項目的主要目標是提高安全性。"},{"w":"prime","p":"adj.","d":"","c":"主要的, 最重要的","s":"The building is in a prime location in the city center.","t":"這棟建築位於市中心的黃金位置。"},{"w":"prime","p":"n.","d":"","c":"鼎盛時期","s":"Many believe that the athlete is now in his prime.","t":"許多人認為這位運動員現在正處於他的全盛時期。"}]},{"unit":14,"theme":"amaze – indistinguishable","cards":[{"w":"amaze","p":"v.","d":"","c":"使驚訝；使驚奇","s":"The total solar eclipse amazed millions of people around the world.","t":"全日食令世界各地的數百萬人感到驚奇。"},{"w":"amazing","p":"adj.","d":"","c":"令人驚奇的；驚人的","s":"The progress in AI development is amazing!","t":"人工智能發展的進步令人驚嘆！"},{"w":"be amazed at","p":"phr.","d":"","c":"對...感到驚奇","s":"Many were amazed at the 3D printed food technology.","t":"許多人對3D打印食物技術感到驚奇。"},{"w":"crop","p":"v.","d":"","c":"作物；收成；種植","s":"The wheat crop in Ukraine has been greatly affected by the war.","t":"烏克蘭的小麥收成受到戰爭的嚴重影響。"},{"w":"influence","p":"n.","d":"","c":"影響；作用","s":"The wars in Ukraine and Israel have had a significant influence on global politics.","t":"烏克蘭和以色列的戰爭對全球政治產生了重大影響。"},{"w":"have a...influence on...","p":"phr.","d":"","c":"對...有影響","s":"AI development has had a profound influence on various industries.","t":"人工智能的發展對各行業產生了深遠影響。"},{"w":"influence","p":"v.","d":"","c":"影響；左右","s":"Recent earthquakes in Taiwan influenced the agricultural sector.","t":"最近在台灣發生的地震對農業部門產生了影響。"},{"w":"influential","p":"adj.","d":"","c":"有影響力的；有權勢的","s":"He is an influential figure in the field of AI research.","t":"他在人工智能研究領域是一位有影響力的人物。"},{"w":"mankind","p":"n.","d":"","c":"人類","s":"The wars remind us of the destructive nature of mankind's conflicts.","t":"戰爭提醒我們人類衝突的破壞性本質。"},{"w":"human being","p":"n.","d":"","c":"人類","s":"The earthquakes in Taiwan have shown the resilience of human beings.","t":"台灣的地震顯示了人類的韌性。"},{"w":"humanity","p":"n.","d":"","c":"人性；人道；人類","s":"The conflicts highlight the need for compassion and understanding in humanity.","t":"衝突凸顯了對人性的同情和理解的需求。"},{"w":"significance","p":"n.","d":"","c":"重要性；意義","s":"The total solar eclipse holds great significance for astronomers.","t":"全日食對天文學家來說意義重大。"},{"w":"significant","p":"adj.","d":"","c":"重要的；顯著的","s":"The development of AI has had a significant impact on various industries.","t":"人工智能的發展對各行業產生了顯著影響。"},{"w":"significantly","p":"adv.","d":"","c":"顯著地；重大地","s":"The earthquake significantly affected the region's infrastructure.","t":"地震對該地區的基礎設施產生了重大影響。"},{"w":"insignificant","p":"adj.","d":"","c":"無關緊要的；微不足道的","s":"Some people consider the AI development to be insignificant compared to other global issues.","t":"一些人認為與其他全球問題相比，人工智能發展微不足道。"},{"w":"importance","p":"n.","d":"","c":"重要性；重要程度","s":"The importance of renewable energy sources is increasingly recognized.","t":"對可再生能源的重視程度越來越高。"},{"w":"important","p":"adj.","d":"","c":"重要的；重大的","s":"It is important to conduct thorough research before making decisions.","t":"在做出決定之前進行深入的研究是非常重要的。"},{"w":"unimportant","p":"adj.","d":"","c":"不重要的；無關緊要的","s":"Some people argue that the issue is unimportant compared to other global challenges.","t":"一些人認為與其他全球挑戰相比，這個問題不重要。"},{"w":"wheat","p":"n.","d":"","c":"小麥","s":"The war has disrupted the wheat harvest in the region.","t":"這場戰爭擾亂了該地區的小麥收成。"},{"w":"climate","p":"n.","d":"","c":"氣候；風氣","s":"The changing climate patterns have led to unpredictable weather.","t":"變化中的氣候模式導致了不可預測的天氣。"},{"w":"sauce","p":"n.","d":"","c":"醬汁","s":"The new sauce recipe uses locally sourced ingredients.","t":"這種新的醬汁食譜使用當地的食材。"},{"w":"saucer","p":"n.","d":"","c":"碟子；茶托","s":"She placed the cup on the saucer next to her.","t":"她把杯子放在了她旁邊的碟子上。"},{"w":"means","p":"n.","d":"","c":"方法；手段","s":"One means to reduce carbon emissions is to use renewable energy.","t":"減少碳排放的一種方法是使用可再生能源。"},{"w":"by all means","p":"phr.","d":"","c":"當然可以；務必","s":"If you have any questions, by all means ask the instructor.","t":"如果你有任何問題，務必向講師提問。"},{"w":"by no means","p":"phr.","d":"","c":"絕不；決不","s":"The new policy is by no means perfect, but it's a step in the right direction.","t":"這項新政策絕不完美，但是這是朝著正確方向邁出的一步。"},{"w":"under no circumstances","p":"phr.","d":"","c":"絕不；在任何情況下都不","s":"Under no circumstances should you give out your personal information to strangers.","t":"你絕對不應該向陌生人透露你的個人信息。"},{"w":"namely","p":"adv.","d":"","c":"即；也就是","s":"There are several countries involved, namely Russia and China.","t":"有幾個國家參與其中，包括俄羅斯和中國。"},{"w":"prove","p":"v.","d":"","c":"證明；證實","s":"Recent studies prove that the vaccine is effective against the virus.","t":"最近的研究證明疫苗對這種病毒是有效的。"},{"w":"proof","p":"n.","d":"","c":"證據；證明","s":"The data provides proof that the theory is correct.","t":"這些數據提供了理論正確性的證據。"},{"w":"proven","p":"adj.","d":"","c":"證明的；被證實的","s":"The new treatment has been proven to be effective.","t":"這種新的治療方法已被證明是有效的。"},{"w":"value","p":"v.","d":"","c":"價值；重要性；估值；看重","s":"It's important to value the opinions of others.","t":"重視他人的意見是很重要的。"},{"w":"valuable","p":"adj.","d":"","c":"有價值的；寶貴的","s":"The experience gained from volunteering is valuable for personal growth.","t":"從志願工作中獲得的經驗對個人成長很有價值。"},{"w":"invaluable","p":"adj.","d":"","c":"非常寶貴的；無價的","s":"Her guidance throughout the project has been invaluable to us.","t":"她在整個項目中的指導對我們來說是無價的。"},{"w":"priceless","p":"adj.","d":"","c":"無價的；極其珍貴的","s":"The support of friends and family is priceless during difficult times.","t":"在困難時期，朋友和家人的支持是無價的。"},{"w":"undervalue","p":"v.","d":"","c":"低估；輕視","s":"It's easy to undervalue the importance of mental health.","t":"很容易低估心理健康的重要性。"},{"w":"overvalue","p":"v.","d":"","c":"高估；過分重視","s":"Some people tend to overvalue their own opinions.","t":"有些人傾向於過分重視自己的意見。"},{"w":"core values","p":"phr.","d":"","c":"核心價值觀","s":"The company's core values include integrity and teamwork.","t":"公司的核心價值觀包括誠信和團隊合作。"},{"w":"place great value/emphasis/stress on...","p":"phr.","d":"","c":"對...非常重視","s":"The school places great emphasis on character education.","t":"這所學校非常重視品德教育。"},{"w":"protein","p":"n.","d":"","c":"蛋白質","s":"Vegetarians often look for alternative sources of protein in their diet.","t":"素食者通常在飲食中尋找蛋白質的替代來源。"},{"w":"mineral","p":"n.","d":"","c":"礦物質","s":"Some minerals are essential for maintaining good health.","t":"一些礦物質對保持健康至關重要。"},{"w":"vitamin","p":"n.","d":"","c":"維生素","s":"It's important to get enough vitamins through diet or supplements.","t":"通過飲食或補充劑攝取足夠的維生素是很重要的。"},{"w":"carbohydrate","p":"n.","d":"","c":"碳水化合物","s":"Athletes need to consume enough carbohydrates for energy.","t":"運動員需要攝取足夠的碳水化合物來獲得能量。"},{"w":"fiber","p":"n.","d":"","c":"纖維","s":"A diet rich in fiber is important for digestive health.","t":"富含纖維的飲食對消化健康很重要。"},{"w":"nutrient","p":"n.","d":"","c":"營養素","s":"Fruits and vegetables are rich in essential nutrients.","t":"水果和蔬菜富含必需的營養素。"},{"w":"nutrition","p":"n.","d":"","c":"營養","s":"Proper nutrition is essential for overall health.","t":"適當的營養對總體健康至關重要。"},{"w":"nutritious","p":"adj.","d":"","c":"營養豐富的","s":"A balanced diet should include a variety of nutritious foods.","t":"均衡的飲食應該包含各種營養豐富的食物。"},{"w":"basis","p":"n.","d":"","c":"基礎；根據","s":"The decision was made on a regular basis after careful consideration.","t":"經過仔細考慮，這個決定是根據定期的基礎做出的。"},{"w":"on a regular basis","p":"phr.","d":"","c":"定期地","s":"He exercises on a regular basis to stay healthy.","t":"他定期運動以保持健康。"},{"w":"on the basis of","p":"phr.","d":"","c":"根據；基於","s":"The report was written on the basis of the latest research findings.","t":"這份報告是根據最新的研究結果撰寫的。"},{"w":"base","p":"v.","d":"","c":"基地；基礎；基於","s":"The company's decision was based on market research.","t":"公司的決定是基於市場研究的。"},{"w":"basic","p":"adj.","d":"","c":"基本的；基礎的","s":"Basic knowledge of computer programming is required for this job.","t":"這份工作需要基本的電腦編程知識。"},{"w":"basically","p":"adv.","d":"","c":"基本上；基本地","s":"Basically, the system works by converting sunlight into electricity.","t":"基本上，這個系統是通過將陽光轉換為電能來工作的。"},{"w":"increase","p":"n.","d":"","c":"增加；增長","s":"There has been an increase in demand for renewable energy sources.","t":"對可再生能源的需求有所增加。"},{"w":"increase","p":"v.","d":"","c":"增加；增長","s":"The company plans to increase its production capacity next year.","t":"公司計劃明年增加其生產能力。"},{"w":"increasing","p":"adj.","d":"","c":"不斷增加的；增長的","s":"There is an increasing demand for skilled workers in the industry.","t":"行業對熟練工人的需求不斷增加。"},{"w":"increasingly","p":"adv.","d":"","c":"日益增加地；越來越多地","s":"The use of AI is increasingly common in various industries.","t":"人工智能在各行各業中的使用越來越普遍。"},{"w":"decrease","p":"n.","d":"","c":"減少；減少量","s":"There has been a significant decrease in air pollution levels.","t":"空氣污染水平顯著下降。"},{"w":"decrease","p":"v.","d":"","c":"減少；降低","s":"The company plans to decrease its carbon emissions by 20% next year.","t":"公司計劃明年將碳排放減少20%。"},{"w":"decreasing","p":"adj.","d":"","c":"逐漸減少的；減少中的","s":"The price of solar panels has been decreasing due to advances in technology.","t":"太陽能板的價格由於技術進步而逐漸降低。"},{"w":"decreasingly","p":"adv.","d":"","c":"逐漸減少地；越來越少地","s":"The use of fossil fuels is decreasingly common as renewable energy sources become more popular.","t":"隨著可再生能源的普及，化石燃料的使用逐漸減少。"},{"w":"diet","p":"n.","d":"","c":"飲食；日常飲食","s":"A balanced diet is essential for good health.","t":"均衡的飲食對健康至關重要。"},{"w":"diet","p":"v.","d":"","c":"節食；戒食","s":"She decided to diet in order to lose weight.","t":"她決定節食以減肥。"},{"w":"be on a diet","p":"phr.","d":"","c":"在節食中；在戒食中","s":"He's on a diet to improve his health.","t":"他正在節食以改善健康。"},{"w":"dietary","p":"adj.","d":"","c":"飲食的；日常飲食的","s":"It's important to have a balanced dietary intake.","t":"保持均衡的飲食攝入量很重要。"},{"w":"fast","p":"v.","d":"","c":"禁食；斋戒","s":"Some people choose to fast for religious reasons.","t":"一些人選擇出於宗教原因而禁食。"},{"w":"delicious","p":"adj.","d":"","c":"美味的；可口的","s":"The restaurant is known for its delicious seafood dishes.","t":"這家餐廳以其美味的海鮮菜而聞名。"},{"w":"tasty","p":"adj.","d":"","c":"美味的；可口的","s":"The soup was tasty and flavorful.","t":"這湯又美味又香。"},{"w":"vegan","p":"adj.","d":"","c":"素食主義者；純素的","s":"She has been a vegan for several years now.","t":"她已經是一名素食主義者好幾年了。"},{"w":"vegetarian","p":"adj.","d":"","c":"素食主義者；素食的","s":"The restaurant offers a variety of vegetarian options.","t":"這家餐廳提供多種素食選擇。"},{"w":"vegetation","p":"n.","d":"","c":"植被；草木","s":"The vegetation in the region has been affected by the drought.","t":"該地區的植被受到乾旱的影響。"},{"w":"distinguish","p":"v.","d":"","c":"區分；辨別","s":"It can be difficult to distinguish between the two species.","t":"在這兩個物種之間進行區分可能很困難。"},{"w":"distinguished","p":"adj.","d":"","c":"卓越的；傑出的","s":"He is a distinguished scientist known for his groundbreaking research.","t":"他是一位以開創性研究而聞名的傑出科學家。"},{"w":"indistinguishable","p":"adj.","d":"","c":"難以區分的；看不出差別的","s":"The two products are almost indistinguishable in terms of quality.","t":"這兩種產品在質量上幾乎看不出差別。"}]},{"unit":15,"theme":"risk – communicator","cards":[{"w":"risk","p":"v.","d":"","c":"冒險","s":"He decided to risk a large portion of his savings by investing in a volatile market.","t":"他決定冒險把大部分積蓄投資在波動的市場上。"},{"w":"risk","p":"n.","d":"","c":"風險","s":"There is always a risk involved in starting your own business.","t":"創業總是存在風險的。"},{"w":"risky","p":"adj.","d":"","c":"危險的","s":"It's a risky business venture that may or may not yield profits.","t":"這是一個有可能會賺錢或賠錢的危險商業冒險。"},{"w":"take a risk","p":"phr.","d":"","c":"冒險","s":"Sometimes you need to take a risk to achieve your goals.","t":"有時候你需要冒險才能達成你的目標。"},{"w":"at risk of","p":"phr.","d":"","c":"有...風險","s":"He is at risk of losing his job due to the company's financial troubles.","t":"由於公司財務困難，他有失去工作的風險。"},{"w":"disappear","p":"v.","d":"","c":"消失","s":"The sun will disappear behind the clouds soon, creating a magical sunset.","t":"太陽很快會在雲層後消失，創造出一個神奇的日落。"},{"w":"appear","p":"v.","d":"","c":"出現","s":"She will appear on stage at the concert tonight, surprising her fans.","t":"她今晚將在音樂會上出現在舞台上，讓她的粉絲們感到驚訝。"},{"w":"appearance","p":"n.","d":"","c":"出現","s":"His sudden appearance at the meeting startled everyone.","t":"他在會議上突如其來的出現讓每個人都感到驚訝。"},{"w":"complete","p":"v.","d":"","c":"完成","s":"Please complete the assignment by Friday so we can review it over the weekend.","t":"請在星期五之前完成作業，這樣我們可以在周末審閱它。"},{"w":"complete","p":"adj.","d":"","c":"完整的","s":"The complete project proposal was submitted to the committee for review.","t":"完整的項目提議已提交給委員會審閱。"},{"w":"create","p":"v.","d":"","c":"創造","s":"Artists create beauty through their paintings and sculptures.","t":"藝術家通過他們的繪畫和雕塑創造美麗。"},{"w":"creature","p":"n.","d":"","c":"生物","s":"The forest is home to many unique creatures that are rarely seen elsewhere.","t":"這片森林是許多在其他地方很少見的獨特生物的家園。"},{"w":"creator","p":"n.","d":"","c":"創造者","s":"Picasso is regarded as one of the greatest creators of modern art.","t":"皮卡索被認為是現代藝術的偉大創作者之一。"},{"w":"creation","p":"n.","d":"","c":"創造","s":"The artist's latest creation is a masterpiece that reflects her talent and vision.","t":"藝術家最新的創作是一件反映她才華和遠見的傑作。"},{"w":"creative","p":"adj.","d":"","c":"創造的","s":"She has a creative approach to problem-solving that often yields innovative solutions.","t":"她對解決問題有創造性的方法常常產生創新的解決方案。"},{"w":"creativity","p":"n.","d":"","c":"創造力","s":"His creativity as a writer shines through in his ability to craft compelling stories.","t":"作為一名作家，他的創造力在於他能夠創作引人入勝的故事。"},{"w":"stubborn","p":"adj.","d":"","c":"固執的","s":"Despite her parents' advice, she stubborn insisted on pursuing her own career path.","t":"儘管父母的建議，她還是固執地堅持走自己的職業道路。"},{"w":"favor A over/to B","p":"v.","d":"","c":"偏愛A勝過B","s":"He tends to favor his younger son over his elder daughter.","t":"他傾向於偏愛他的小兒子而不是他的大女兒。"},{"w":"favor","p":"n.","d":"","c":"恩惠","s":"Can you do me a favor and pick up my mail while I'm away?","t":"在我不在的時候，你能幫我個忙，去拿我的郵件嗎？"},{"w":"do sb. a favor","p":"phr.","d":"","c":"幫忙某人","s":"Could you do a favor for me and pick up my mail?","t":"你能幫我取郵件嗎？"},{"w":"be in favor of","p":"phr.","d":"","c":"支持","s":"I'm in favor of reducing plastic use in our office.","t":"我支持減少辦公室使用塑料。"},{"w":"favorable","p":"adj.","d":"","c":"有利的，良好的","s":"The weather conditions were favorable for our outdoor event.","t":"天氣條件對我們的戶外活動非常有利。"},{"w":"favorite","p":"adj.","d":"","c":"最喜愛的，最喜愛的事物","s":"My favorite color is blue. All my clothes are in blue.","t":"我最喜歡的顏色是藍色。"},{"w":"bother","p":"v.","d":"","c":"打擾，困擾","s":"Sorry to bother you, but could I ask you a quick question?","t":"抱歉打擾你，但我可以問你個問題嗎？"},{"w":"refuse","p":"v.","d":"","c":"拒絕","s":"He refuses to participate in the project.","t":"他拒絕參與這個項目。"},{"w":"refusal","p":"n.","d":"","c":"拒絕","s":"Her refusal to accept the offer surprised everyone.","t":"她拒絕接受這個提議讓大家都感到驚訝。"},{"w":"reject","p":"v.","d":"","c":"拒絕","s":"They rejected the proposal due to budget constraints.","t":"由於預算限制，他們拒絕了這個提議。"},{"w":"decline","p":"v.","d":"","c":"下降","s":"Sales declined after the price increase.","t":"價格上漲後銷售量下降了。"},{"w":"decline","p":"v.","d":"","c":"拒絕","s":"The applicant declined the job offer because of the low payment the company offers.","t":"應徵者拒絕這個工作機會因為薪水太低"},{"w":"mate","p":"v.","d":"","c":"配偶，伴侶，交配","s":"The birds mate for life. They die as their husband or wife dies.","t":"這些鳥會終生配對。"},{"w":"put off / postpone","p":"phr.","d":"","c":"延期，拖延","s":"They decided to put off the meeting until next week.","t":"他們決定將會議推遲到下週。"},{"w":"sense","p":"n.","d":"","c":"感覺，感知，意識","s":"He lost his sense of smell and taste after getting COVID.","t":"他得到新冠後喪失嗅覺與味覺"},{"w":"sense / notice / realize","p":"v.","d":"","c":"察覺，感覺到","s":"She sensed a change in the atmosphere as soon as she entered.","t":"她一進來就感覺到氣氛有所變化。"},{"w":"be sensitive to N","p":"phr.","d":"","c":"敏感於","s":"She's sensitive to changes in temperature.","t":"她對溫度變化很敏感。"},{"w":"sensitivity","p":"n.","d":"","c":"敏感性","s":"The patient's sensitivity to light increased after the surgery.","t":"病人手術後對光的敏感性增加了。"},{"w":"sensible","p":"adj.","d":"","c":"明智的，理智的","s":"It's sensible to wear sunscreen in hot weather.","t":"在炎熱的天氣中擦防曬霜是明智的。"},{"w":"contain","p":"v.","d":"","c":"包含，容納","s":"This box contains all the items I need for the trip.","t":"這個盒子包含了我旅行所需的所有物品。"},{"w":"contain","p":"v.","d":"","c":"抑制，遏阻","s":"The government is trying to contain violence and panic.","t":"政府努力要抑制疾病和病毒的蔓延與暴力和恐慌的擴大"},{"w":"container","p":"n.","d":"","c":"容器","s":"The food was stored in a plastic container for transport.","t":"食物存放在一個塑料容器中進行運輸。"},{"w":"inform sb of sth","p":"phr.","d":"","c":"通知某人某事","s":"Please inform me of any changes to the schedule.","t":"請通知我任何日程安排的變更。"},{"w":"communication","p":"n.","d":"","c":"溝通，交流","s":"Effective communication is key to a successful team.","t":"有效的溝通是團隊成功的關鍵。"},{"w":"communicator","p":"n.","d":"","c":"溝通者，交流者","s":"She's a skilled communicator who can engage with diverse audiences.","t":"她是一位熟練的溝通者，能夠與不同的觀眾交流。"}]},{"unit":16,"theme":"perfume – acclaim","cards":[{"w":"perfume","p":"n.","d":"","c":"香水","s":"She loves the scent of roses in her perfume collection.","t":"她喜歡她的香水收藏中玫瑰的香味。"},{"w":"develop","p":"v.","d":"","c":"使發展;開發;形成","s":"The company plans to develop new software next year.","t":"公司計劃明年開發新軟件。"},{"w":"development","p":"n.","d":"","c":"發展","s":"The city's rapid development has led to increased employment.","t":"這座城市的快速發展導致了就業增加。"},{"w":"developing","p":"adj.","d":"","c":"發展中的","s":"Many countries in Africa are developing nations.","t":"非洲的許多國家是發展中國家。"},{"w":"pleasant","p":"adj.","d":"","c":"令人愉快的","s":"It was a pleasant surprise to see her at the party.","t":"在派對上見到她真是一個愉快的驚喜。"},{"w":"please","p":"v.","d":"","c":"使高興;滿意","s":"His efforts to please his boss were successful.","t":"他設法使老板滿意的努力是成功的。"},{"w":"unpleasant","p":"adj.","d":"","c":"令人不愉快的","s":"The weather turned unpleasant just as we started our picnic.","t":"我們剛開始野餐時天氣變得不愉快。"},{"w":"expand","p":"v.","d":"","c":"擴大;增加;發展","s":"The company plans to expand its operations overseas.","t":"公司計劃擴展其海外業務。"},{"w":"expand/widen/broaden sb.'s horizons","p":"n.","d":"","c":"拓展視野;廣見聞","s":"Traveling to new places can broaden your horizons.","t":"到新地方旅行可以拓展你的視野。"},{"w":"expansion","p":"n.","d":"","c":"擴展","s":"The rapid expansion of the city led to infrastructure improvements.","t":"城市的快速擴展促使基礎設施改善。"},{"w":"expansive","p":"adj.","d":"","c":"擴張的","s":"Her expansive gestures showed her enthusiasm.","t":"她的大手勢顯示出她的熱情。"},{"w":"possibility","p":"n.","d":"","c":"可能性;可能","s":"There's a strong possibility of rain later today.","t":"今天晚些時候很有可能會下雨。"},{"w":"possible","p":"adj.","d":"","c":"可能的","s":"Is it possible to finish this project by Friday?","t":"這個項目能在星期五完成嗎？"},{"w":"entry","p":"n.","d":"","c":"進入權;參加","s":"Admission is free upon entry to the museum.","t":"進入博物館免費。"},{"w":"gain entry into","p":"n.","d":"","c":"進入","s":"He managed to gain entry into the exclusive club.","t":"他成功進入了這個專屬俱樂部。"},{"w":"spray","p":"v.","d":"","c":"噴灑;噴劑","s":"She sprays perfume on her neck before going out.","t":"她在出門前在脖子上噴了香水。"},{"w":"blend","p":"v.","d":"","c":"(使)混合;融合","s":"Blend the ingredients thoroughly for a smooth texture.","t":"將成分充分混合以獲得光滑的質地。"},{"w":"blender","p":"n.","d":"","c":"攪拌機","s":"She used a blender to make a fruit smoothie.","t":"她用攪拌機做了果汁冰沙。"},{"w":"outcome","p":"n.","d":"","c":"結果","s":"The outcome of the negotiations was favorable for both parties.","t":"談判的結果對雙方都是有利的。"},{"w":"concept","p":"n.","d":"","c":"觀念;概念","s":"Understanding the concept of sustainability is crucial.","t":"理解可持續發展的概念是至關重要的。"},{"w":"conception","p":"n.","d":"","c":"概念;構想;想法","s":"His conception of justice influenced his decisions.","t":"他對正義的概念影響了他的決定。"},{"w":"misconception","p":"n.","d":"","c":"錯誤觀念;誤解","s":"There's a common misconception that cats always land on their feet.","t":"人們普遍誤解貓總是能落在腳上。"},{"w":"shift","p":"v.","d":"","c":"改變;轉移","s":"The shift in public opinion was noticeable after the scandal.","t":"丑聞後公眾意見的轉變是顯著的。"},{"w":"conventional","p":"adj.","d":"","c":"傳統上的;常規的","s":"Their wedding was very conventional, with all the traditional rituals.","t":"他們的婚禮非常傳統，包括所有傳統儀式。"},{"w":"unconventional","p":"adj.","d":"","c":"不因循守舊的","s":"Her unconventional approach to solving problems impressed her colleagues.","t":"她不按常規解決問題的方法給同事留下了深刻的印象。"},{"w":"convention","p":"n.","d":"","c":"慣例","s":"It's a convention to shake hands when you meet someone new.","t":"與陌生人見面時握手是慣例。"},{"w":"overcome","p":"v.","d":"","c":"戰勝;克服","s":"She managed to overcome her fear of public speaking.","t":"她成功地克服了對公開演講的恐懼。"},{"w":"be overcome with","p":"n.","d":"","c":"被...所克服","s":"He was overcome with emotion when he won the award.","t":"當他獲得獎項時，他充滿了情感。"},{"w":"boldness","p":"n.","d":"","c":"勇敢;大膽","s":"The soldier showed great boldness in the face of danger.","t":"士兵在危險面前展示了偉大的勇氣。"},{"w":"bold","p":"adj.","d":"","c":"醒目的;大膽的","s":"Her bold decision to quit her job surprised everyone.","t":"她大膽地決定辭去工作讓大家都感到驚訝。"},{"w":"favorable","p":"adj.","d":"","c":"贊成的;稱的;肯定的","s":"The weather conditions were favorable for sailing.","t":"天氣條件對航行是有利的。"},{"w":"unfavorable","p":"adj.","d":"","c":"令人不快的;不利的","s":"The unfavorable outcome of the negotiations disappointed us.","t":"談判的不利結果讓我們感到失望。"},{"w":"review","p":"v.","d":"","c":"評價;評論","s":"She wrote a positive review of the movie for the newspaper.","t":"她為報紙寫了一篇對電影的正面評論。"},{"w":"rumor","p":"v.","d":"","c":"謠傳;傳言","s":"Don't spread rumors about others; it can be harmful.","t":"別輕易傳言他人，這可能會有害。"},{"w":"deliver","p":"v.","d":"","c":"提供;運送;投遞","s":"He delivered a heartfelt apology to his friend.","t":"他向朋友誠摯地道歉。"},{"w":"deliver a speech","p":"n.","d":"","c":"發表演講","s":"She was nervous about delivering a speech at the conference.","t":"她對在會議上發表演講感到緊張。"},{"w":"delivery","p":"n.","d":"","c":"遞送;運送","s":"The courier service provides fast delivery of packages.","t":"快遞服務提供快速的包裹遞送。"},{"w":"molecule","p":"n.","d":"","c":"分子","s":"A water molecule is made of two hydrogen atoms and one oxygen atom.","t":"一個水分子由兩個氫原子和一個氧原子組成。"},{"w":"pheromone","p":"n.","d":"","c":"費洛蒙(昆蟲分泌以刺激同種昆蟲之化合物質)","s":"Ants use pheromones to communicate with each other.","t":"螞蟻使用費洛蒙彼此溝通。"},{"w":"acclaim","p":"v.","d":"","c":"為...歡呼;稱讚","s":"The actor was acclaimed for his outstanding performance in the play.","t":"這位演員因其在劇中出色的表演而受到稱讚。"}]},{"unit":17,"theme":"specific – scratch","cards":[{"w":"specific","p":"adj.","d":"","c":"特定的","s":"Can you provide more specific details about the incident?","t":"你能提供更具體的事件細節嗎？"},{"w":"specify","p":"v.","d":"","c":"具體說明","s":"Please specify which items you need from the list.","t":"請指明您需要清單上的哪些項目。"},{"w":"analyze","p":"v.","d":"","c":"分析","s":"Scientists need to analyze the data before drawing conclusions.","t":"科學家需要分析數據才能得出結論。"},{"w":"analysis","p":"n.","d":"","c":"分析","s":"The financial analysis showed a decline in profits.","t":"財務分析顯示利潤下降。"},{"w":"analyst","p":"n.","d":"","c":"分析師","s":"The market analyst predicted a rise in stock prices.","t":"市場分析師預測股價上漲。"},{"w":"location","p":"n.","d":"","c":"位置","s":"The exact location of the treasure remains unknown.","t":"寶藏的確切位置仍然未知。"},{"w":"locate","p":"v.","d":"","c":"找出⋯的位置","s":"We need to locate the source of the problem before we can fix it.","t":"我們需要找出問題的根源才能解決它。"},{"w":"remote","p":"adj.","d":"","c":"偏遠的","s":"Their village is remote and difficult to reach.","t":"他們的村莊偏遠且難以到達。"},{"w":"recognize","p":"v.","d":"","c":"認出","s":"I recognize him from the photograph.","t":"我從照片上認出了他。"},{"w":"recognizable","p":"adj.","d":"","c":"可辨認的","s":"Her voice is recognizable even in a noisy room.","t":"她的聲音在嘈雜的房間裡也是可以辨認的。"},{"w":"recognition","p":"n.","d":"","c":"辨認","s":"His recognition of the suspect was crucial to the investigation.","t":"他對嫌疑人的辨認對調查至關重要。"},{"w":"harmony","p":"n.","d":"","c":"和諧","s":"The choir sang in perfect harmony.","t":"合唱團的表演聲音和諧無比。"},{"w":"harmonious","p":"adj.","d":"","c":"融洽的","s":"They had a harmonious relationship with their neighbors.","t":"他們與鄰居之間有著融洽的關係。"},{"w":"determine","p":"v.","d":"","c":"判定","s":"It's difficult to determine the exact cause of the problem.","t":"很難判定問題的確切原因。"},{"w":"determined","p":"adj.","d":"","c":"堅定的","s":"She was determined to finish the marathon despite the rain.","t":"她下著雨也堅決要完成馬拉松賽。"},{"w":"determination","p":"n.","d":"","c":"決心","s":"His determination to succeed kept him going through difficult times.","t":"他成功的決心支持他度過了困難時期。"},{"w":"accuracy","p":"n.","d":"","c":"準確","s":"The accuracy of his predictions surprised everyone.","t":"他預測的準確性讓所有人都感到驚訝。"},{"w":"accurate","p":"adj.","d":"","c":"準確的","s":"Her answers were accurate and well-researched.","t":"她的答案準確且經過深入研究。"},{"w":"vary","p":"v.","d":"","c":"有差異","s":"Prices vary depending on the time of year.","t":"價格因年份不同而有所不同。"},{"w":"variation","p":"n.","d":"","c":"變化","s":"There is a variation in temperature between day and night.","t":"白天和晚上的溫度有所不同。"},{"w":"various","p":"adj.","d":"","c":"多種的","s":"The store sells various types of imported chocolates.","t":"這家商店出售多種進口巧克力。"},{"w":"varying","p":"adj.","d":"","c":"變化的","s":"His mood was varying; you never knew how he would react.","t":"他的心情變化無常，你永遠不知道他會有什麼反應。"},{"w":"rare","p":"adj.","d":"","c":"罕見的","s":"It's rare to find such old books in such good condition.","t":"在這樣良好的狀況下找到這麼老的書是非常罕見的。"},{"w":"occasion","p":"n.","d":"","c":"場合","s":"On special occasions, we go out for dinner.","t":"在特殊場合，我們出去吃飯。"},{"w":"cooperate","p":"v.","d":"","c":"合作","s":"The two companies agreed to cooperate on the new project.","t":"這兩家公司同意在新項目上進行合作。"},{"w":"cooperation","p":"n.","d":"","c":"合作","s":"Cooperation between departments is crucial for the project's success.","t":"各部門之間的合作對項目的成功至關重要。"},{"w":"exchange","p":"v.","d":"","c":"交換","s":"We need to exchange ideas to improve our strategy.","t":"我們需要交換意見來改進我們的策略。"},{"w":"ignore","p":"v.","d":"","c":"忽視","s":"You can't ignore the importance of regular exercise.","t":"你不能忽視定期運動的重要性。"},{"w":"ignorance","p":"n.","d":"","c":"(對某事物)不了解","s":"His ignorance of the rules led to his disqualification.","t":"他對規則的無知導致了他的被取消資格。"},{"w":"function","p":"v.","d":"","c":"起作用","s":"The new machine didn't function properly.","t":"這台新機器的功能不正常。"},{"w":"functional","p":"adj.","d":"","c":"起作用的","s":"Is the printer functional","t":"打印機正常工作嗎？"},{"w":"malfunction","p":"v.","d":"","c":"故障","s":"There was a malfunction in the system that caused the delay.","t":"系統出現故障導致了延誤。"},{"w":"territory","p":"n.","d":"","c":"領土","s":"The cats marked their territory with scent.","t":"貓用氣味標記了他們的領土。"},{"w":"survive","p":"v.","d":"","c":"倖存下來","s":"He managed to survive the harsh winter with limited resources.","t":"他設法在資源有限的情況下度過了嚴冬。"},{"w":"survival","p":"n.","d":"","c":"生存","s":"Survival skills are essential for outdoor enthusiasts.","t":"對於戶外愛好者來說，生存技能至關重要。"},{"w":"identify","p":"v.","d":"","c":"識別","s":"Can you identify the person in this photograph?","t":"你能識別這張照片中的這個人嗎？"},{"w":"identification","p":"n.","d":"","c":"身分證明","s":"The suspect's identification was confirmed by fingerprints.","t":"嫌疑人的身份被指紋確認了。"},{"w":"identity","p":"n.","d":"","c":"身份","s":"She struggled to maintain her cultural identity while living abroad.","t":"她在國外生活時努力維持她的文化身份。"},{"w":"evidence","p":"n.","d":"","c":"證據","s":"The police found DNA evidence linking the suspect to the crime scene.","t":"警方找到了將嫌疑人與犯罪現場聯繫起來的DNA證據。"},{"w":"capacity","p":"n.","d":"","c":"能力","s":"The stadium has a seating capacity of 50,000 people.","t":"這個體育場的容納能力為50,000人。"},{"w":"capable","p":"adj.","d":"","c":"有能力的","s":"She's capable of handling the project on her own.","t":"她有能力獨立完成這個項目。"},{"w":"demonstrate","p":"v.","d":"","c":"示範說明","s":"He will demonstrate the new software to the team tomorrow.","t":"明天他將向團隊示範這款新軟件。"},{"w":"demonstration","p":"n.","d":"","c":"示範","s":"The scientist gave a demonstration of the experiment at the conference.","t":"科學家在會議上對實驗進行了示範。"},{"w":"demonstrator","p":"n.","d":"","c":"示威者","s":"The demonstrators marched through the streets to protest peacefully.","t":"示威者在街上遊行以和平抗議。"},{"w":"scratch","p":"v.","d":"","c":"抓;擦傷;刮擦聲","s":"I scratched my arm on the rough wall.","t":"我把手臂擦傷在粗糙的牆上。"},{"w":"scratch","p":"n.","d":"","c":"抓;擦傷;刮擦聲","s":"He felt a scratch on his arm after climbing the rough wall.","t":"他爬粗糙的牆後感到手臂上有一處擦傷。"}]},{"unit":18,"theme":"cinema – emerge","cards":[{"w":"cinema","p":"n.","d":"","c":"電影院;戲院","s":"They went to the cinema to watch the latest blockbuster.","t":"他們去電影院看最新的大片。"},{"w":"cinematic","p":"adj.","d":"","c":"電影的;電影風格的","s":"The film had a cinematic quality that captivated the audience.","t":"這部電影有一種電影風格的質感，吸引了觀眾。"},{"w":"essential","p":"adj.","d":"","c":"關鍵的;重要的;必不可少的","s":"Exercise is essential for maintaining good health.","t":"運動對保持健康是必不可少的。"},{"w":"essence","p":"n.","d":"","c":"本質;精華","s":"The essence of his argument was clear and persuasive.","t":"他的論點的精華明確而有說服力。"},{"w":"entertain","p":"v.","d":"","c":"娛樂;使快樂","s":"The magician will entertain the children at the birthday party.","t":"魔術師將在生日派對上娛樂孩子們。"},{"w":"entertainment","p":"n.","d":"","c":"娛樂;表演","s":"The theme park offers a variety of entertainment for visitors.","t":"這個主題公園為遊客提供各種娛樂活動。"},{"w":"entertaining","p":"adj.","d":"","c":"有趣的;使人愉悅的","s":"The comedian's jokes were entertaining and made everyone laugh.","t":"這個喜劇演員的笑話很有趣，讓每個人都笑了起來。"},{"w":"entertainer","p":"n.","d":"","c":"表演者;娛樂家","s":"The singer is a talented entertainer who performs regularly at the club.","t":"這位歌手是一位才華橫溢的表演者，經常在俱樂部演出。"},{"w":"direct","p":"v.","d":"","c":"指導;引導","s":"The coach will direct the team during the match.","t":"教練將在比賽期間指導球隊。"},{"w":"direct","p":"adj.","d":"","c":"直接的;直率的","s":"His direct approach to problem-solving is effective.","t":"他對解決問題的直接方法是有效的。"},{"w":"indirect","p":"adj.","d":"","c":"間接的","s":"She used an indirect route to avoid traffic.","t":"她走了一條間接路線以避開交通。"},{"w":"director","p":"n.","d":"","c":"導演","s":"The director of the movie won several awards for his work.","t":"這部電影的導演因其工作而獲得了幾個獎項。"},{"w":"direction","p":"n.","d":"","c":"方向;指導","s":"Follow the directions on the map to reach the destination.","t":"按照地圖上的方向走到目的地。"},{"w":"directly","p":"adv.","d":"","c":"直接地","s":"You can directly contact me if you have any questions.","t":"如果你有任何問題，可以直接與我聯繫。"},{"w":"indirectly","p":"adv.","d":"","c":"間接地","s":"She learned about the news indirectly from her friend.","t":"她從朋友那裡間接得知了這則消息。"},{"w":"silence","p":"n.","d":"","c":"寂靜;沉默","s":"The silence in the room was awkward after the argument.","t":"爭吵後房間裡的寂靜令人尷尬。"},{"w":"silent","p":"adj.","d":"","c":"沉默的","s":"The library was silent except for the sound of pages turning.","t":"除了書頁翻動聲以外，圖書館裡一片寂靜。"},{"w":"fair","p":"adj.","d":"","c":"公平的;合理的","s":"The judge made a fair decision based on the evidence.","t":"法官根據證據作出了公正的判斷。"},{"w":"fair","p":"adj.","d":"","c":"清楚的;晴朗的","s":"We had fair weather for our outdoor event.","t":"我們的戶外活動天氣晴朗。"},{"w":"fair","p":"n.","d":"","c":"展;市集","s":"We visited the fair to see the local crafts.","t":"我們參觀了市集看當地的手工藝品。"},{"w":"fairly","p":"adv.","d":"","c":"相當地","s":"She performed fairly well in the competition.","t":"她在比賽中表現相當好。"},{"w":"stage","p":"n.","d":"","c":"舞台","s":"The actors gathered on stage before the play.","t":"演員們在劇前聚集在舞台上。"},{"w":"stage","p":"v.","d":"","c":"上演","s":"The theater will stage the new play next month.","t":"這家劇院將在下個月上演新劇。"},{"w":"inventor","p":"n.","d":"","c":"發明者","s":"Thomas Edison is a famous inventor in history.","t":"湯瑪斯·愛迪生是歷史上著名的發明者。"},{"w":"invention","p":"n.","d":"","c":"發明","s":"The telephone was a groundbreaking invention.","t":"電話是一項開創性的發明。"},{"w":"invent","p":"v.","d":"","c":"發明","s":"He tried to invent a new type of engine.","t":"他試圖發明一種新型引擎。"},{"w":"proper","p":"adj.","d":"","c":"適當的","s":"It's important to wear proper attire for the interview.","t":"面試時穿著適當的服裝很重要。"},{"w":"improper","p":"adj.","d":"","c":"不適當的","s":"It's considered improper to arrive late without notice.","t":"沒有通知就遲到被視為不適當。"},{"w":"properly","p":"adv.","d":"","c":"正確地","s":"Please read the instructions properly before assembling.","t":"請在組裝前仔細閱讀說明。"},{"w":"decade","p":"n.","d":"","c":"十年","s":"He has worked for over a decade in this company.","t":"他在這家公司工作了十年以上。"},{"w":"nearly","p":"adv.","d":"","c":"幾乎","s":"They are nearly finished with the project.","t":"他們幾乎完成了這個項目。"},{"w":"dialogue","p":"n.","d":"","c":"對話","s":"The movie has witty dialogue between the characters.","t":"電影中角色之間的對話很機智。"},{"w":"inspire","p":"v.","d":"","c":"激勵","s":"Her bravery inspires others to take action.","t":"她的勇敢激勵了其他人採取行動。"},{"w":"inspiring","p":"adj.","d":"","c":"鼓舞人心的","s":"The speaker gave an inspiring speech at the conference.","t":"演講者在會議上發表了一篇鼓舞人心的演講。"},{"w":"inspiration","p":"n.","d":"","c":"靈感","s":"The painting was his inspiration for the new novel.","t":"這幅畫是他創作新小說的靈感。"},{"w":"creativity","p":"n.","d":"","c":"創造力","s":"The company encourages creativity among its employees.","t":"公司鼓勵員工發揮創造力。"},{"w":"create","p":"v.","d":"","c":"創造","s":"Artists create works of art that evoke emotions.","t":"藝術家創造了能唤起情感的藝術品。"},{"w":"creative","p":"adj.","d":"","c":"有創造力的","s":"She has a creative approach to problem-solving.","t":"她在解決問題時有創造性的方法。"},{"w":"creation","p":"n.","d":"","c":"創作","s":"The museum displayed a new creation by a local artist.","t":"博物館展示了一位本地藝術家的新作品。"},{"w":"career","p":"n.","d":"","c":"職業","s":"He has had a successful career as a lawyer.","t":"他在律師職業上取得了成功。"},{"w":"fame","p":"n.","d":"","c":"名聲","s":"Her fame grew after she won the award.","t":"她在獲獎後名聲大噪。"},{"w":"hardship","p":"n.","d":"","c":"艱難","s":"They faced many hardships during the war.","t":"他們在戰爭期間面臨了許多艱難。"},{"w":"dramatically","p":"adv.","d":"","c":"戲劇性地","s":"The company's profits increased dramatically last year.","t":"公司去年的利潤戲劇性增長。"},{"w":"drama","p":"n.","d":"","c":"戲劇","s":"The play is a classic drama of love and betrayal.","t":"這部戲劇是愛與背叛的經典之作。"},{"w":"dramatic","p":"adj.","d":"","c":"戲劇的","s":"There was a dramatic change in the weather.","t":"天氣出現了戲劇性的變化。"},{"w":"overdramatic","p":"adj.","d":"","c":"過分戲劇化的","s":"She tends to be overdramatic about minor issues.","t":"她對小事情往往過分戲劇化。"},{"w":"switch","p":"n.","d":"","c":"開關","s":"Please flip the switch to turn on the light.","t":"請切換開關打開燈。"},{"w":"emergence","p":"n.","d":"","c":"出現","s":"The emergence of new technologies is changing industries.","t":"新技術的出現正在改變行業。"},{"w":"emerge","p":"v.","d":"","c":"浮現","s":"He managed to emerge from the difficult situation.","t":"他設法從困境中浮現出來。"}]}];
